var e=JSON.parse(`{"wrist-circles":{"name":"Handgelenkskreise","description":"Steh aufrecht, Ellbogen locker, Unterarme vor dir. Zeichne langsame Kreise mit beiden Handgelenken, vier Zählzeiten in die eine, vier in die andere Richtung, Finger locker lassen.","goodFor":"Wärmt Handgelenke und Unterarme auf, die bei jedem Prop die Hauptarbeit leisten.","alignmentCues":["Ellbogen bleiben still; nur die Handgelenke bewegen sich.","Halte die Kreise groß und flüssig."],"commonMistakes":["Die Kreise hetzen, sodass sie zu Schnippern werden."]},"arm-circles":{"name":"Armkreise","description":"Füße hüftbreit, Arme lang. Schwing beide Arme vier Zählzeiten lang in großen Vorwärtskreisen, dann vier rückwärts, und lass die Schulterblätter gleiten.","goodFor":"Öffnet die Schultern für Staff-Spins und Hoop-Arbeit über dem Kopf.","alignmentCues":["Rippen bleiben unten, während die Arme über den Kopf ziehen.","Atme beim Abschwung aus."]},"shoulder-rolls":{"name":"Schulterrollen","description":"Arme entspannt an den Seiten. Heb die Schultern zu den Ohren, roll sie nach hinten und unten, und wiederhole das in einer langsamen Schleife.","goodFor":"Löst Spannung, die Würfe steif und kurz macht."},"neck-rolls":{"name":"Halbe Nackenkreise","description":"Senk das Kinn zur Brust und führ es langsam in einem Halbkreis von Schulter zu Schulter. Kopf nicht nach hinten kippen lassen.","goodFor":"Entlastet den Nacken, bevor du lange nach oben zu Würfen schaust.","avoidIf":["Nackenverletzung oder Schwindel bei Kopfbewegungen."]},"hip-circles":{"name":"Hüftkreise","description":"Hände an die Hüften, Knie weich. Kreis die Hüften langsam zwei Takte in die eine und zwei in die andere Richtung, Kopf bleibt waagerecht.","goodFor":"Bereitet die Hüften auf Waist Hooping vor und den Körper auf Flow."},"torso-twists":{"name":"Rumpfdrehungen","description":"Füße weit, Arme locker. Dreh die Rippen nach links und rechts und lass die Arme schwingen und um dich wickeln wie leere Ärmel.","goodFor":"Weckt die Rotation für Staff-Weaves und Hoop-Pässe."},"knee-bounce":{"name":"Knie-Bounce","description":"Steh mit den Füßen unter den Hüften und federe sanft auf jeder Zählzeit durch die Knie, Arme schwingen locker. Finde die Musik in deinen Beinen.","goodFor":"Bringt den Beat in deinen Körper, bevor du einen Prop aufnimmst."},"one-ball-toss":{"name":"Ein-Ball-Wurf","description":"Halte einen Ball in der rechten Hand auf Hüfthöhe. Schöpf ihn ein und wirf ihn dann in einem Bogen, der knapp über Augenhöhe seinen Scheitelpunkt hat und in die linke Hand fällt. Wirf ihn auf dieselbe Weise zurück. Blick auf den Scheitelpunkt, nicht auf die Hände.","goodFor":"Baut den Bogen auf, aus dem jedes Jongliermuster besteht.","alignmentCues":["Ellbogen an den Seiten, Unterarme waagerecht.","Der Scheitelpunkt ist bei jedem Wurf gleich hoch.","Fang auf Hüfthöhe und lass die Hand ein wenig nachgeben."],"commonMistakes":["Nach vorne werfen, sodass du dem Ball nachsteigen musst.","Auf die Hände schauen statt auf den Scheitelpunkt."]},"two-ball-exchange":{"name":"Zwei-Ball-Austausch","description":"Ein Ball in jeder Hand. Wirf den rechten Ball in seinem Bogen; wenn er den Scheitelpunkt erreicht, wirf den linken Ball darunter auf der Innenseite. Fang beide und halte kurz inne. Dann beginne mit der linken Hand.","goodFor":"Lehrt den Austausch: Der zweite Wurf kommt, wenn der erste den Scheitelpunkt erreicht.","alignmentCues":["Zweiter Wurf am Scheitelpunkt, niemals früher.","Wirf den zweiten Ball innerhalb des ersten."],"commonMistakes":["Den zweiten Ball rübergeben statt ihn zu werfen.","Beide gleichzeitig werfen."]},"cascade":{"name":"Drei-Ball-Kaskade","description":"Zwei Bälle in der rechten Hand, einer in der linken. Wirf von rechts; wenn er den höchsten Punkt erreicht, wirf von links; wenn der seinen höchsten Punkt erreicht, wirf wieder von rechts. Jeder Wurf kommt auf den Beat und kreuzt in einem Achterbogen zur anderen Hand.","goodFor":"Das Grundmuster des Jonglierens.","modifications":["Übe den Flash: drei Würfe, drei Fänge, Stopp."],"deepen":["Jongliere zu einem schnelleren Tempo mit niedrigeren Gipfeln.","Zähle 20 Fänge ohne Drop."],"alignmentCues":["Wirf von innen, fange außen.","Gipfel auf gleicher Höhe, auf Augenhöhe.","Stell dich an eine Wand, wenn du immer nach vorne läufst."],"commonMistakes":["Nach vorne werfen und dem Muster hinterherjagen.","Hetzen, sobald ein Wurf schiefgeht."]},"reverse-cascade":{"name":"Reverse Cascade","description":"Die Kaskade von innen nach außen gedreht: Jeder Ball wird von außen über die Spitze des Musters geworfen und fällt in der Mitte in die andere Hand.","goodFor":"Trainiert Würfe von außen und öffnet Tricks wie den Mills Mess.","alignmentCues":["Würfe schleifen über den ankommenden Ball.","Fang in der Mitte."]},"siteswap-423":{"name":"423","description":"Ein Drei-Ball-Muster: ein hoher Eigenwurf (4), ein gehaltener Ball (2), dann ein Kaskadenwurf (3). Die 4 geht auf derselben Seite hoch; die 2 wird einfach einen Beat lang gehalten.","goodFor":"Dein erster Siteswap-Trick: lehrt hohe Würfe und Halten."},"siteswap-441":{"name":"441","description":"Zwei hohe Würfe, die auf ihrer eigenen Seite bleiben (4, 4), gefolgt von einem schnellen Zip rüber (1) von Hand zu Hand.","goodFor":"Baut Timing zwischen hohen Würfen und schnellen Pässen auf."},"two-in-one":{"name":"Zwei in einer Hand","description":"Jongliere zwei Bälle in einer Hand in nebeneinanderliegenden Säulen oder kleinen Kreisen nach außen, ein Wurf auf jedem zweiten Beat. Übe jede Hand.","goodFor":"Der Baustein des Vier-Ball-Jonglierens."},"siteswap-531":{"name":"531","description":"Ein sehr hoher Kreuzwurf (5), ein Kaskadenwurf (3) und ein schneller Zip (1). Die 5 geht hoch, während die anderen zwei Bälle darunter weiterarbeiten.","goodFor":"Höhenkontrolle und ein Showtrick mit drei Bällen."},"shower":{"name":"Drei-Ball-Shower","description":"Die Bälle wandern im Kreis: Die rechte Hand wirft jeden Ball hoch nach links, und die linke Hand gibt jeden direkt zurück nach rechts.","goodFor":"Klassisches kreisförmiges Muster; trainiert schnelle Hand-zu-Hand-Pässe."},"mills-mess":{"name":"Mills Mess","description":"Eine Drei-Ball-Kaskade, bei der die Arme sich ständig kreuzen und wieder öffnen, sodass jeder Wurf von der gegenüberliegenden Körperseite kommt. Die Ballwege zeichnen ein webendes Muster.","goodFor":"Ein berühmter Publikumsliebling, der die Koordination schärft."},"four-ball-fountain":{"name":"Vier-Ball-Fountain","description":"Jede Hand jongliert zwei Bälle in ihrer eigenen Säule, die Hände wechseln sich mit den Würfen ab, sodass das Muster nie kreuzt.","goodFor":"Dein erstes Vier-Ball-Muster."},"sync-fountain":{"name":"Synchrone Fountain","description":"Vier Bälle, bei denen beide Hände genau im selben Moment werfen, jede auf ihre eigene Seite.","goodFor":"Baut Symmetrie auf und führt zu Sync-Tricks."},"five-ball-cascade":{"name":"Fünf-Ball-Kaskade","description":"Die Cascade mit fünf Bällen: hohe, schnelle Würfe in einem hohen überkreuzenden Muster. Rechne mit Monaten des Übens.","goodFor":"Ein Meilenstein für engagierte Jongleure."},"staff-wheel-spin":{"name":"Zwei-Hand-Rad-Spin","description":"Halte den Staff in der Mitte mit beiden Händen, Handflächen nach unten, auf Brusthöhe. Drehe ihn an deiner Seite wie ein Rad, indem du die Rotation zwischen den Händen weitergibst und ihn neben deinem Körper hältst.","goodFor":"Der erste Staff-Spin; baut Griff und Handgelenksrotation auf.","alignmentCues":["Der Staff bleibt parallel zu deinem Körper, ohne zu kippen.","Sanfter Griff: lass ihn durch die Finger rollen."],"props":["Staff"],"commonMistakes":["Zu fest zudrücken, sodass der Spin stockt.","Die Ebene nach vorne kippen."]},"staff-front-spin":{"name":"Front Windmill","description":"Drehe den Staff vor dir wie einen Propeller, in der Wall Plane, und gib ihn sanft von Hand zu Hand um sein Zentrum weiter.","goodFor":"Fügt die Wall Plane und das Hand-über-Hand-Weitergeben hinzu.","props":["Staff"]},"staff-figure-8":{"name":"Figure-8 Weave","description":"Drehe den Staff in der Wheel Plane auf deiner rechten Seite, kreuze ihn dann auf deine linke Seite und drehe dort, wobei du eine Acht vor dir ziehst.","goodFor":"Verbindet beide Körperseiten; das Rückgrat des Staff Flow.","alignmentCues":["Wechsle die Seiten, wenn die Enden den Boden passieren.","Drehe den Oberkörper mit jeder Seite ein wenig mit."],"props":["Staff"]},"staff-pass-through":{"name":"Pass-Through","description":"Drehe in der Wall Plane, aber lass bei jeder halben Umdrehung los: Eine Hand lässt den Staff los und die andere fängt ihn in der Mitte, sodass der Staff zwischen deinen Händen durchgeht.","goodFor":"Lehrt das Timing von Loslassen und Fangen.","props":["Staff"]},"staff-one-hand-spin":{"name":"One-Hand Spin","description":"Drehe den Staff vor dir mit einer Hand und rolle ihn über den Handrücken und durch die Finger. Übe beide Hände.","goodFor":"Finger- und Handgelenkskraft; macht die andere Hand für Tricks frei.","props":["Staff"]},"staff-helicopter":{"name":"Overhead Helicopter","description":"Hebe den Staff über den Kopf und drehe ihn flach in der Floor Plane mit einer Hand, wie Hubschrauberrotorblätter.","goodFor":"Führt die Floor Plane ein.","props":["Staff"]},"staff-butterfly":{"name":"Butterfly","description":"Drehe vor dir, falte den Staff dann hinter deine Schulter und wieder heraus, wobei du auf jeder Seite vorne und hinten wie Flügel abwechselst.","goodFor":"Schultermobilität und ein fließender Übergang von vorne nach hinten.","props":["Staff"]},"staff-behind-back-pass":{"name":"Behind-the-Back Pass","description":"Gib den sich drehenden Staff am unteren Punkt des Spins hinter deinem Rücken von einer Hand in die andere und bring ihn dann nach vorne.","goodFor":"Body Wraps und Show-Pässe.","props":["Staff"]},"staff-isolation":{"name":"Staff-Isolation","description":"Halte den Staff nahe an einem Ende und kreise deine Hand um die Mitte des Staffs, sodass die Mitte scheinbar an derselben Stelle in der Luft bleibt, während sich der Staff um sie dreht.","goodFor":"Illusionsarbeit und präzise Handwege.","props":["Staff"]},"staff-antispin-flower":{"name":"Vierblättriger Antispin","description":"Kreise deine Hand in eine Richtung, während der Staff dreimal so schnell in die andere Richtung spinnt, sodass der Staff eine vierblättrige Blume zeichnet.","goodFor":"Die ikonische VTG-Blume; tiefe Timing-Kontrolle.","props":["Staff"]},"staff-neck-roll":{"name":"Nackenrolle","description":"Lass den Staff auf deinen Schulterrücken fallen und rolle ihn über den Nacken zur anderen Hand. Fang langsam an mit einem gepolsterten Staff.","goodFor":"Contact Staff: Der Staff bewegt sich am Körper ohne Hände.","avoidIf":["Nackenschmerzen."],"props":["Staff"]},"hoop-waist":{"name":"Taillen-Hooping","description":"Steh mit einem Fuß leicht vor dem anderen. Halte den Hoop an deinen unteren Rücken, wirf ihn um deine Taille und stoße den Bauch nach vorne und hinten (nicht im Kreis) jedes Mal, wenn der Hoop vorne vorbeikommt.","goodFor":"Die erste Hoop-Fähigkeit; baut den Kernrhythmus auf.","modifications":["Nimm einen größeren, schwereren Hoop: Er dreht sich langsamer."],"alignmentCues":["Schwinge vorne und hinten, nicht im Kreis.","Drücke den Hoop, wenn er an deinem Bauch vorbeikommt."],"props":["Hoop"],"commonMistakes":["Die Hüften wie ein Hula-Tänzer kreisen lassen.","Ein Hoop, der zu klein oder zu leicht ist."]},"hoop-hand-spin":{"name":"Hand-Spin","description":"Halte den Hoop vor dir mit der Hand darin, Daumen nach oben. Stoße ihn in einen Spin um das Handnetz, wobei der Hoop flach vor dir bleibt.","goodFor":"Off-Body-Hoop-Grundlage.","props":["Hoop"]},"hoop-chest":{"name":"Brust-Hooping","description":"Hebe deine Arme über den Kopf und hoope um die Brust, wobei du den Brustkorb vorne und hinten schwingst und die Hüften ruhig hältst.","goodFor":"Isoliert den Brustkorb und baut Oberkörperkontrolle auf.","props":["Hoop"]},"hoop-lasso":{"name":"Lasso","description":"Halte den Hoop über dem Kopf und kreise ihn flach über deinem Kopf wie ein Lasso, wobei der Hoop um deine Hand spinnt.","goodFor":"Bodenebenen-Kontrolle über dem Kopf.","props":["Hoop"]},"hoop-wedgie":{"name":"Wedgie","description":"Spinne den Hoop in der Wandebene und fange ihn in der Mulde zwischen Daumen und Fingern, lass ihn dort rollen und schaukeln, bevor du weiterspinnst.","goodFor":"Griffkontrolle und ein sanfter Übergangshalt.","props":["Hoop"]},"hoop-knees":{"name":"Knie-Hooping","description":"Mit geschlossenen Füßen halte den Hoop um deine Knie in Bewegung, indem du die Knie nach vorne und hinten stößt.","goodFor":"Hula-Hoop für den Unterkörper und Escalator üben.","props":["Hoop"]},"hoop-pass":{"name":"Hand-to-Hand Pass","description":"Lass den Hoop vor dir kreisen und gib ihn bei jeder Umdrehung von einer Hand in die andere, während die Ebene stabil bleibt.","goodFor":"Links off-body Tricks auf beiden Seiten.","props":["Hoop"]},"hoop-isolation":{"name":"Hoop-Isolation","description":"Bewege deine Hand um den Hoop herum, sodass sein Mittelpunkt vor dir in der Luft stehen bleibt, während der Hoop um diesen Punkt kreist.","goodFor":"Die klassische Hoop-Illusion.","props":["Hoop"]},"hoop-escalator":{"name":"Escalator","description":"Halte den Hoop in Bewegung, während du ihn von der Taille zu den Knien und wieder hoch zur Brust wanderst – eine Körperzone pro Takt.","goodFor":"Verbindet alle Body-Hooping-Zonen zu einem Flow.","props":["Hoop"]},"hoop-neck":{"name":"Neck Hooping","description":"Neige den Kopf leicht und lass einen leichten Hoop um den Hals kreisen, geführt von kleinen Impulsen aus Kopf und Schultern.","goodFor":"Ein Show-Move, der kleine, präzise Impulse trainiert.","avoidIf":["Nackenschmerzen."],"props":["Hoop"]},"shake-out":{"name":"Shake Out","description":"Leg die Props weg und schüttle Hände und Unterarme aus. Lass die Schultern fallen.","goodFor":"Ein kurzer Reset zwischen harten Runs."},"breathe":{"name":"Atmen und Reset","description":"Steh still, schließe oder entspanne die Augen und atme langsam durch die Nase ein und durch den Mund aus.","goodFor":"Senkt den Puls und löst Frust nach Drops.","breathCue":"Vier ein, vier aus."}}`),t={"warmup-mobility":{name:`Flow-Warm-up`,description:`Handgelenke, Schultern, Wirbelsäule und Hüften locker im gleichmäßigen Beat. Nutze es vor jeder Prop-Session.`,focus:`Warm-up · Mobility`},"first-throws":{name:`Erste Würfe`,description:`Ein Ball im Bogen von Hand zu Hand auf Augenhöhe, dann der Zwei-Ball-Austausch, aus dem jedes Muster wächst.`,focus:`Jonglieren · Grundlagen`},"cascade-builder":{name:`Cascade-Aufbau`,description:`Zwei-Ball-Austausch hintereinander, bis der dritte Ball dazukommt: kurze Cascade-Runs, Reset, wieder los.`,focus:`Jonglieren · Grundlagen`},"juggling-tempo-ladder":{name:`Cascade-Tempoleiter`,description:`Die Cascade in drei Tempi, jede Stufe ein paar Beats schneller. Für die schnellen Stufen die Würfe tiefer halten.`,focus:`Jonglieren · Tempo`},"siteswap-sampler":{name:`Siteswap-Sampler`,description:`Cascade in 423, 441 und 531, mit Reverse Cascade und Shower als Gaumenputzer. Jedes Muster beginnt und endet in der Cascade.`,focus:`Jonglieren · Muster`},"four-ball-session":{name:`Vier-Ball-Session`,description:`Zwei in einer Hand für jede Seite, der Vier-Ball-Fountain, dann der synchrone Fountain.`,focus:`Jonglieren · Zahlen`},"juggling-combo-flow":{name:`Jonglier-Combo-Flow`,description:`Ein langes fließendes Set: Cascade, Reverse Cascade, Mills Mess und die Siteswaps zu einem Musikstück verbunden.`,focus:`Jonglieren · Combos`},"staff-first-spins":{name:`Erste Staff-Spins`,description:`Der Wheel Spin neben dem Körper, dann der Front Spin. Langsame, gleichmäßige Drehungen, eine pro Beat.`,focus:`Staff · Grundlagen`},"staff-foundations":{name:`Staff-Grundlagen`,description:`Wheel Spin, Front Spin, Figure 8 und der Hand-to-Hand Pass-Through, auf dem Beat verbunden.`,focus:`Staff · Grundlagen`},"staff-flow-weave":{name:`Staff-Flow-Weave`,description:`Figure 8 in Butterfly, One-Hand-Spins und der Helicopter, so verbunden, dass der Staff nie stehen bleibt.`,focus:`Staff · Flow`},"staff-isolation-lab":{name:`Staff-Isolation-Lab`,description:`Isolations und die Antispin Flower bei langsamerem Tempo, mit Behind-the-Back-Passes dazwischen.`,focus:`Staff · Technik`},"staff-advanced-flow":{name:`Staff Advanced Flow`,description:`Das volle Vokabular in einem langen Stück: Weaves, Wraps, Isolations und der Neck Roll.`,focus:`Staff · Flow`},"hoop-first-spins":{name:`Erste Hoop-Spins`,description:`Waist Hooping mit einem Front-Back-Push, dann den Hoop um eine Hand drehen.`,focus:`Hoop · Grundlagen`},"hoop-body-flow":{name:`Hoop On-Body Flow`,description:`Den Hoop hoch zur Brust und runter zu den Knien und zurück zur Taille bewegen, ohne anzuhalten.`,focus:`Hoop · On-Body`},"hoop-off-body":{name:`Off-Body Hoop`,description:`Hand Spins, Lasso, Wedgies und Passes, zum Abschluss Isolations, die den Hoop still im Raum halten.`,focus:`Hoop · Off-Body`},"hoop-full-flow":{name:`Hoop Full Flow`,description:`On-Body und Off-Body zusammen: Escalators, Neck Hooping und die Off-Body-Tricks in einem langen Flow.`,focus:`Hoop · Flow`},"daily-mixed-flow":{name:`Täglicher Mixed Flow`,description:`Ein bisschen von jeder Kunst: Cascade, Staff-Spins und Hooping, mit einer Mobility-Move zwischen den Props.`,focus:`Mixed · Practice`}},n=JSON.parse(`{"start-here":{"title":"Start hier: deine erste Flow-Woche","summary":"Wähle ein Prop, übe zehn Minuten am Tag auf dem Beat, und lass den Unlock Tree dir sagen, was als Nächstes kommt.","imageAlt":"3D-Figur, die einen einzelnen Jonglierball von Hand zu Hand wirft","body":["Flow Arts sehen von außen wie Magie aus: Bälle, die in der Luft hängen, ein Staff, der zu einem Wisch wird, ein Hoop, der eine Tänzerin umkreist, die sich kaum zu bewegen scheint. Von innen sind sie ein Stapel sehr kleiner Fähigkeiten, jede an einem Nachmittag lernbar, geschichtet, bis der Stapel mühelos aussieht. Deine erste Woche dreht sich um die unterste Ebene dieses Stapels.","Wähle ein Prop für den Anfang. Jonglieren lehrt Timing und Hand-Auge-Koordination; Staff lehrt Ebenen und flüssige Handwechsel; Hoop lehrt Rhythmus durch den ganzen Körper. Du kannst alle drei lernen, aber eins nach dem anderen hält deine Aufmerksamkeit dort, wo der Fortschritt ist. Der Rewards-Baum zeigt jede Bewegung für jede Kunst, vom ersten Wurf oder Spin bis zu fortgeschrittenen Patterns, und öffnet die nächsten, wenn du beherrschst, worauf sie aufbauen.","Übe wenig und oft. Zehn fokussierte Minuten am Tag schlagen eine Stunde am Sonntag, weil Koordination zwischen den Einheiten gefestigt wird, besonders im Schlaf. Eine kurze Routine von der Routines-Seite, ein Warm-up und ein paar gezählte Schritte deiner aktuellen Bewegung sind eine vollständige Practice.","Übe vom ersten Tag an auf den Beat. Jede Bewegung in SynthFlow wird in Takten zu einem Tempo gezählt, mit Musik oder generierter Perkussion, die dazu passt. Der Beat gibt dir etwas, woran du dich festhalten kannst, wenn das Prop nicht mitspielt, und er macht Fortschritt messbar: ein sauberer Run bei 90 BPM diese Woche, 100 nächste Woche.","Rechne mit Drops. Jeder lässt fallen, auch Profis im Training. Ein Drop sagt dir, welcher Wurf oder Catch Aufmerksamkeit braucht; über Talent sagt er nichts. Heb das Prop auf, warte auf den nächsten Downbeat und weiter. Am Ende der Woche hast du eine Bewegung, die du ohne Nachdenken kannst, und das ist der Moment, in dem Flow beginnt."]},"counting-and-the-beat":{"title":"Counts, Takte und der Beat","summary":"Warum jede Bewegung in Takten zu einem Tempo gezählt wird und wie du deine Würfe und Spins auf die Musik legst.","imageAlt":"3D-Figur, die eine Drei-Ball-Kaskade jongliert, mit Bögen über den Händen","body":["Musik besteht aus Beats, die in Takte gruppiert sind, meist vier Beats pro Takt. Flow-Bewegungen bestehen aus Zyklen: ein Wurf aus jeder Hand, eine halbe Drehung des Staffs, eine Umlaufbahn des Hoops. Wenn ein Zyklus auf den Beat fällt, werden Bewegung und Musik eins. Deshalb misst SynthFlow jeden Routine-Schritt in Takten statt in Sekunden, und deshalb sagt jede Bewegung, wie viele Beats ein Zyklus dauert.","In einer Drei-Ball-Kaskade fällt jeder Wurf auf einen Beat, abwechselnd rechts und links. Beim Staff-Frontspin dauert eine halbe Drehung meist einen Beat. Hooping an der Taille ist bei entspanntem Tempo üblicherweise eine Umlaufbahn pro Beat. Die Counts im Player benennen, was auf jedem Beat passiert, und die 3D-Figur bewegt sich exakt auf derselben Uhr wie das Audio, sodass du sie im Takt nachmachen kannst.","Tempo wird in Beats pro Minute (BPM) gemessen. Jede Bewegung hat einen angenehmen Bereich: langsam genug, um sauber zu bleiben, schnell genug, dass das Prop seinen Schwung behält. Unterhalb des Bereichs bleiben Spinning Props stehen und Würfe gehen so hoch, dass sie abdriften; oberhalb beginnst du zu hetzen und lässt fallen. Der Builder warnt dich, wenn ein Schritt außerhalb des Bereichs seiner Bewegung liegt.","Beginne jeden Schritt auf dem Downbeat, der „Eins“ des Takts. Der Count-in gibt dir einen Takt, um das Prop in Bewegung zu bringen, bevor die gezählten Takte beginnen. Wenn du den Beat verlierst, jage ihm nicht nach: Stopp, höre auf die nächste „Eins“ und steig wieder ein. Musiker nennen das, die Spitze des Takts finden, und für Flow Artists funktioniert es genauso.","Ein paar Einheiten lang laut mitzuzählen hilft mehr, als es scheint. „Eins, zwei, drei, vier“ zu sagen, während du jonglierst, verbindet den Rhythmus mit deinem Atem und deiner Stimme, sodass er überlebt, wenn das Pattern schwer wird. Sobald die Counts in deinem Körper leben, schalte die gesprochenen Counts in den Settings aus und lass dich von der Musik tragen."]},"tempo-ladders":{"title":"Tempo-Leitern: langsam ist flüssig, flüssig ist schnell","summary":"Steigere dich in kleinen BPM-Schritten von einem Tempo, das du sauber kannst, und geh sofort eine Stufe zurück, wenn die Form bricht.","imageAlt":"3D-Figur, die einen Staff in der Wall Plane vor dem Körper spinnt","body":["Eine Tempo-Leiter ist dieselbe Bewegung bei steigenden Tempi: acht Takte bei 80 BPM, acht bei 88, acht bei 96 und so weiter. Sie ist der zuverlässigste Weg, eine Bewegung schneller zu machen, ohne sie schlampiger zu machen, und mehrere integrierte Routinen sind darum herum aufgebaut.","Starte auf einer Sprosse, die du sauber kannst, auch wenn sie sich zu leicht anfühlt. Der Sinn der untersten Sprosse ist nicht die Herausforderung; sie ist das Einüben korrekter Form, damit genau diese Form schneller wird. Steig um einen kleinen Betrag hoch, etwa fünf bis zehn Prozent. Große Sprünge verändern die Bewegung: Würfe werden niedriger, Spins flacher, und du übst am Ende einen anderen Trick.","Hör auf zu klettern, wenn die Form bricht, nicht wenn du fallen lässt. Achte auf die frühen Anzeichen: Peaks werden ungleichmäßig, der Staff driftet aus seiner Ebene, der Hoop wandert hoch oder runter. Das sind die Signale, eine Sprosse zurückzugehen und sie erneut zu laufen. Eine Leiter mit einem sauberen Run knapp unter deinem Limit zu beenden, lehrt deinen Körper dieses Tempo; sie mit einem Crash zu beenden, lehrt den Crash.","Langsame Tempi sind für Spinning Props schwerer, als sie aussehen, weil das Prop weniger Schwung hat, um durchzukommen. Wenn ein Staff oder Hoop am unteren Ende seines Bereichs stehen bleibt, behalte das Tempo und vergrößere die Bewegung leicht, oder nimm sie in Halftime mit der Musik: ein Zyklus alle zwei Beats.","Verfolge dein höchstes sauberes Tempo für jede Bewegung in Progress. Zu sehen, wie diese Zahl über Wochen steigt, ist gute Motivation, und sie zeigt auch, wann eine Bewegung ein Plateau erreicht hat und eine andere Übung braucht statt mehr vom Gleichen."]},"siteswap-notation":{"title":"Siteswap: Jonglieren als Zahlen geschrieben","summary":"Jede Zahl sagt, wie viele Beats später ein Ball wieder geworfen wird; ungerade Zahlen kreuzen, gerade bleiben, und der Durchschnitt ist die Ballanzahl.","imageAlt":"3D-Figur, die den Siteswap 441 mit zwei hohen Würfen und einem schnellen Zip jongliert","body":["Jonglier-Patterns sind schwer in Worten und leicht in Zahlen zu beschreiben. Siteswap, Mitte der 1980er unabhängig von Jongleuren in Cambridge, am Caltech und in Santa Cruz entwickelt, schreibt ein Pattern als wiederholte Folge von Ziffern. So teilen Jongleure Patterns, prüfen, ob eine Idee funktionieren kann, und entdecken Tricks, die noch niemand versucht hat. SynthFlow nutzt es, um jedes Jonglier-Pattern aus derselben Engine zu animieren.","Stell dir vor, die Hände werfen abwechselnd auf jedem Beat: rechts, links, rechts, links. Jede Ziffer in einem Siteswap sagt, wie viele Beats von jetzt an der Ball, der auf diesem Beat geworfen wird, wieder geworfen wird. Eine 3 kommt drei Beats später zurück; weil drei ungerade ist, landet sie in der anderen Hand. Eine Drei-Ball-Kaskade ist einfach 3, 3, 3, 3 für immer, kurz geschrieben als 3. Eine 4 kommt vier Beats später in derselben Hand zurück, das ist der Vier-Ball-Fountain.","Kleine Zahlen haben besondere Bedeutungen. Eine 2 kehrt zwei Beats später in dieselbe Hand zurück, was praktisch heißt, den Ball einen Moment zu halten. Eine 1 kreuzt auf dem aller nächsten Beat zur anderen Hand, ein schneller Zip direkt rüber. Eine 0 ist eine leere Hand. Größere Zahlen sind höhere Würfe: eine 5 ist ein hoher kreuzender Wurf.","Lies ein Pattern Ziffer für Ziffer. In 441 bleiben zwei Würfe auf ihrer eigenen Seite, während ein dritter Ball darunter hinweg zippt. In 531 geht ein hoher kreuzender Wurf nach oben, während ein Kaskadenwurf und ein Zip die anderen zwei Bälle in Bewegung halten. In 423 wechseln sich ein Wurf in Fountain-Höhe, ein gehaltener Ball und ein Kaskadenwurf ab.","Das Average Theorem sagt dir, wie viele Bälle ein Pattern braucht: Addiere die Ziffern und teile durch ihre Anzahl. 441 ergibt 9 über drei Ziffern, also drei Bälle. Wenn der Durchschnitt keine ganze Zahl ist, kann die Sequenz nicht jongliert werden. Eine zweite Prüfung ist, dass keine zwei Bälle auf demselben Beat in dieselbe Hand landen dürfen, so erkennen Jongleure unmögliche Patterns, bevor sie sie versuchen.","Siteswap hat auch Notation für beide Hände, die zusammen werfen, geschrieben in Klammern wie (4,4), und für zwei Bälle aus einer Hand gleichzeitig, geschrieben in eckigen Klammern. Du brauchst nichts davon, um gut zu jonglieren, aber sobald die Zahlen klicken, beginnt jeder neue Pattern-Name, sich selbst zu erklären. Öffne das Flow-Glossar für die einzelnen Zahlen."]},"planes-and-geometry":{"title":"Ebenen: Wall, Wheel und Floor","summary":"Spinning Props leben in flachen Ebenen; die Ebene sauber zu halten, ist das meiste, was einen Staff oder Hoop knackig aussehen lässt.","imageAlt":"3D-Figur, die einen Staff in einer Acht auf beiden Seiten des Körpers webt","body":["Ein spinnender Staff oder Hoop fegt über eine flache Fläche, seine Ebene. Flow Artists beschreiben drei grundlegende Ebenen relativ zum Körper. Die Wall Plane ist vor dir, wie eine Glasscheibe, gegen die du deine Handflächen drücken könntest. Die Wheel Plane ist neben dir, so wie ein Wagenrad an deiner Seite dreht. Die Floor Plane ist horizontal, parallel zum Boden, wie bei einem Overhead-Helicopter oder einem Lasso.","Saubere Ebenen sind das, was das Publikum als Skill liest. Ein Staff, der aus seiner Ebene wackelt, wirkt unsicher, auch wenn er nie fällt; ein Hoop, der bei einem Pass perfekt flach bleibt, wirkt mühelos. Der meiste frühe Practice dreht sich still um Ebenen: die Handgelenke am Verdrehen hindern, die Ellbogen am Ausstellen hindern und die Schultern das Prop bewegen lassen statt die Hände.","Viele Tricks sind durch Ebenenwechsel definiert. Ein Figure-8-Weave bewegt den Staff von der Wheel Plane auf einer Seite zur Wheel Plane auf der anderen. Ein Butterfly faltet ihn hinter die Schulter und zurück. Ein Escalator lässt einen Hoop am Körper hoch- und runterlaufen, während seine Ebene waagerecht bleibt. Zu lernen, wo jede Bewegung im Raum beginnt und endet, ist der Weg, sie zu Flow zu verbinden.","Der 3D-Viewer kann die Ebene zeichnen, während du übst. Schalte ihn ein, wenn du einen neuen Spin lernst, und vergleiche: Kippt dein Staff oben zu dir? Taucht der Hoop vorne ab? Ein Spiegel oder eine Handykamera zeigt dasselbe. Aus der Seitenansicht zu schauen, ist besonders nützlich für Wall-Plane-Bewegungen, weil Kippen von vorne unsichtbar ist.","Ebenen helfen auch bei Sicherheit und Raum. Prüfe vor einer Session, dass jede Ebene, die du nutzen wirst, frei ist: die Wand vor dir, die Wände neben dir und die Decke über dir für Floor-Plane- und Overhead-Bewegungen. Eine saubere Ebene, in der nichts ist, ist eine selbstsichere Ebene."]},"spin-and-antispin":{"title":"Spin, Antispin und Isolations","summary":"Wie sich das Prop im Vergleich zur Hand dreht, ergibt drei Familien von Bewegung: Spin, Antispin und Isolation.","imageAlt":"3D-Figur, die mit einem Staff eine vierblättrige Antispin-Blume zeichnet","body":["Wenn du ein rotierendes Prop auf einem Kreis bewegst, passieren zwei Drehungen gleichzeitig: Deine Hand wandert um einen Kreis, und das Prop dreht sich um seinen eigenen Mittelpunkt. Die Flow-Theorie benennt Bewegungen danach, wie diese beiden Drehungen zueinander stehen. Es ist dasselbe Vokabular für Staff, Hoop und Poi, weshalb Skills so gut zwischen Props übertragbar sind.","Beim Spin, manchmal Inspin genannt, dreht sich das Prop in dieselbe Richtung wie der Kreis der Hand. Das ist die natürliche Richtung; die meisten ersten Spins sind Inspin, ohne dass es jemand so nennt. Die gezeichnete Form ist eine Blume, deren Blütenblätter nach außen zeigen.","Beim Antispin dreht sich das Prop entgegen dem Kreis der Hand. Es fühlt sich zuerst seltsam an, wie sich gleichzeitig auf den Kopf klopfen und den Bauch reiben, aber es zeichnet die klassische Blütenblätter-Blume. Die Anzahl der Blütenblätter hängt davon ab, wie oft sich das Prop pro Handkreis dreht: drei Gegenrotationen pro Kreis ergeben vier Blütenblätter, was der Four-Petal Antispin im Staff-Baum ist.","Eine Isolation ist der Sonderfall, bei dem die Hand so kreist, dass ein Punkt des Props im Raum eingefroren erscheint. Beim Staff bleibt der Mittelpunkt still, während die Enden um ihn herumfegen; beim Hoop bleibt der Mittelpunkt des Rings oder ein Punkt am Rand stehen. Isolations sehen aus, als würde das Prop schweben und der Körper es umkreisen. Sie verlangen präzise Handwege, was sie zu exzellentem Training für jeden anderen Trick macht.","Lerne diese langsam und auf den Beat. Besonders Antispin profitiert von einem Tempo deutlich unter deiner normalen Spin-Geschwindigkeit, mit Zählzeiten, die benennen, wo das Prop sein sollte: oben, seitlich, unten, seitlich. Nutze den Ghost im 3D-Viewer, um die Position des nächsten Beats zu sehen, und den Trail, um zu prüfen, ob deine Blume gleichmäßige Blütenblätter hat.","Wenn sich Spin, Antispin und Isolation in einer Ebene vertraut anfühlen, probiere sie in einer anderen. Die Theorie bleibt gleich und dein Körper lernt, dass die Ebene nur eine Einstellung ist, was ein großer Schritt zum Improvisieren von Flow ist."]},"sequencing":{"title":"Wie Flow-Routinen aufgebaut sind","summary":"Aufwärmen, einen Fokus mit Links üben, die fließend weitergehen, Temposprünge klein halten und mit einem leichten Cool-down abschließen.","imageAlt":"3D-Figur, die einen Hoop vor dem Körper von Hand zu Hand gibt","body":["Eine gute Flow-Routine hat dieselbe Form wie ein gutes Musikset: einen Anfang, der den Raum aufwärmt, eine Mitte, die aufbaut, und ein Ende, das alle durchatmen lässt. Die integrierten Routinen von SynthFlow folgen dieser Form, und der Co-Pilot des Builders prüft deine daran.","Beginne mit einem Warm-up. Handgelenkskreise, Armkreise und Schulterrollen bringen die Gelenke, die du belasten wirst, bei sanftem Tempo durch ihren Bewegungsumfang. Zwei oder drei Minuten reichen für eine kurze Session; längere Sessions und kalte Tage verdienen mehr.","Gib dem Übungsblock einen Fokus. Wähle eine Bewegung, an der du arbeitest, und umgib sie mit Bewegungen, die hineinfließen. Der Builder zeigt, wie jeder Schritt mit dem vorherigen verbunden ist: direkt aus derselben Handposition weiterfließen, ein kleiner Umgriff, das Prop absetzen oder auf einem früheren Trick aufbauen. Routinen, die fließend weitergehen, fühlen sich wie Tanzen an; Routinen voller Absetzmomente fühlen sich wie eine Liste an.","Halte Tempoänderungen zwischen den Schritten klein. Ein Sprung von 80 auf 130 BPM setzt dein Timing zurück und lädt Drops ein. Der Co-Pilot markiert Sprünge von mehr als etwa einem Viertel und faltet halbes und doppeltes Tempo, sodass ein Hoop-Schritt bei 70 BPM neben einem Track bei 140 BPM sitzen kann.","Kehre mehr als einmal zur Fokusbewegung zurück. Wiederholung über eine Session hinweg, mit anderen Bewegungen dazwischen, baut Skill besser auf als ein langer Block, weil jede Rückkehr ein frischer Versuch von einem etwas anderen Ausgangspunkt ist.","Schließe mit einem Cool-down ab: eine leichte Bewegung bei langsamem Tempo oder eine kurze Pause mit ein paar Atemzügen. Das senkt die Herzfrequenz und gibt deiner Koordination einen ruhigen Abschluss zum Erinnern. Sieh dir die Routine vor dem Abspielen in der Vorschau an und entferne alles, was eindeutig der Ehrgeiz von gestern ist."]},"effort":{"title":"Wann du das Tempo erhöhen solltest","summary":"Erhöhe, wenn die Form hält und du frisch bist; nimm heraus, wenn Peaks wackeln, der Griff fester wird oder Drops sich häufen.","imageAlt":"3D-Figur, die fünf Bälle in einer hohen Cascade jongliert","body":["Fortschritt im Flow entsteht durch Üben an der Grenze deiner Fähigkeiten, aber die Grenze verschiebt sich. An manchen Tagen liegt sie weiter draußen als erwartet; an manchen Tagen ist sie zurückgewichen. Sie lesen zu lernen ist ein Skill, der so viel wert ist wie jeder Trick.","Erhöhe, wenn die Grundlagen halten. Wenn deine Peaks gleichmäßig sind, dein Staff in seiner Ebene bleibt, dein Hoop waagerecht bleibt und deine Atmung leicht ist, nimm die nächste Sprosse der Tempo-Leiter oder probiere die nächste Übung in der Progression. Die ersten fünfzehn Minuten einer Session nach dem Warm-up sind meist die beste Zeit für neues Material.","Nimm heraus, wenn die Qualität nachlässt. Gehäufte Drops, ein fester werdender Griff, Schultern, die zu den Ohren kriechen, und angehaltener Atem sagen alle, dass dein Nervensystem müde ist. Senke das Tempo, geh zurück zu einer Bewegung, die du beherrschst, oder beende die Session. Sich durch Müdigkeit zu pushen, probt meistens Fehler ein.","Achte auch auf körperliche Warnsignale. Wiederholtes Werfen und Spinnen belastet Handgelenke, Unterarme und Schultern. Ein Schmerz, der innerhalb eines Tages nachlässt, ist normale Anpassung. Stechender Schmerz, Schmerz, der während des Übens zunimmt, Taubheit oder Kribbeln sind Gründe zu stoppen und dich auszuruhen; anhaltende Symptome gehören zu einer Ärztin oder einem Arzt.","Nutze die Anstrengungsbewertung nach jeder Session. Der Practice Wizard liest sie: mehrere harte Sessions in Folge und er schlägt etwas Sanfteres vor, mehrere leichte und er schlägt ein wenig mehr vor. Ehrliche Bewertungen führen zu besseren Vorschlägen."]},"drops-are-data":{"title":"Drops sind Daten","summary":"Ein Drop sagt dir, welchen Wurf oder Catch du korrigieren solltest; ihn als Versagen zu behandeln, lehrt dich nur, dich zu verkrampfen.","imageAlt":"3D-Figur, die zwei Jonglierbälle zwischen den Händen austauscht","body":["Jede Jongleurin und jeder Jongleur hat irgendwann einen Boden voller Bälle. Jede Staff-Spinnerin und jeder Staff-Spinner hat das Klappern gehört. Der Unterschied zwischen Menschen, die sich weiter verbessern, und denen, die aufhören, ist selten Talent; es ist der Umgang mit dem Drop.","Ein Drop ist eine Messung. Er sagt dir, welcher Wurf schiefging, nach welchem Catch du gegriffen hast, welcher Moment des Spins seine Ebene verloren hat. Wenn derselbe Ball immer vor dir landet, driften deine Würfe nach vorn. Wenn Drops nach sechs Würfen kommen, stimmt etwas in deinem dritten oder vierten Wurf nicht. Beobachte wo und wann und wähle dann eine Sache, die du änderst.","Drops als Versagen zu behandeln, hat einen Preis. Angst verspannt die Schultern und verkürzt den Atem, und Spannung macht Bewegungen kleiner und schneller, was mehr Drops verursacht. Die ruhige Reaktion — aufheben, atmen, auf den Downbeat warten, neu starten — ist nicht nur angenehm; sie ist die technisch richtige Reaktion.","Zähle saubere Runs, nicht Drops. SynthFlow meistert eine Bewegung, wenn du genug saubere Runs und Übungsminuten hast, also sind Drops unterwegs einfach Teil der Minuten. An manchen Tagen loggst du zehn saubere Runs, an manchen zwei. Beide Tage zählen.","Lass manchmal absichtlich fallen. Wenn du einen neuen Trick lernst, übe den ersten Wurf oder den ersten halben Spin und lass ihn fallen. Füge dann den Catch hinzu. Den riskanten Moment zu isolieren, verkleinert ihn, und du lernst, dass der Boden nicht dein Feind ist. Er ist einfach dort, wo das Prop hingeht, während du lernst."]},"safety":{"title":"Sicherheit: Raum, Props und rote Flaggen","summary":"Räume deine Ebenen, wähle verzeihende Props, wärme dich auf und stoppe bei stechendem Schmerz, Taubheit oder Schwindel.","imageAlt":"3D-Figur, die einen Staff flach über dem Kopf mit klarem Raum drumherum spinnt","body":["Flow Arts sind im Vergleich zu den meisten Sportarten risikoarm, aber Props bewegen sich schnell und fliegen weiter, als du erwartest. Ein paar Gewohnheiten halten das Üben sicher für dich, die Menschen in deiner Nähe und die Möbel.","Räume deinen Raum, bevor du beginnst. Prüfe jede Ebene, die du nutzen wirst: vorn, an den Seiten und oben. Staff und Hoop brauchen mehr Platz, als du denkst, meist einen Kreis von mindestens Armspannweite plus Proplänge in jede Richtung, mit nichts Zerbrechlichem in Reichweite. Drinnen auf Deckenlampen und Ventilatoren achten; draußen auf unebenen Boden und Passanten.","Nutze verzeihende Props beim Lernen. Jonglierbälle aus Bohnensäckchen rollen nicht weg. Gepolsterte Staffs oder Staffs mit Schaumstoffenden tun weniger weh, wenn sie deinen Kopf treffen, was sie tun werden. Ein größerer, schwererer Hoop dreht langsamer und ist leichter oben zu halten. Steig auf schnellere oder auffälligere Props um, sobald die Grundlagen automatisch sitzen.","Wärme dich vor jeder Session auf und steigere das Volumen allmählich. Werfen und Spinnen sind repetitiv, und wiederholte Belastung auf kaltes Gewebe ist die übliche Ursache für schmerzende Handgelenke und Ellbogen. Wenn du plötzlich viel mehr übst, füge auch Ruhetage hinzu.","Stoppe bei roten Flaggen: stechender oder elektrischer Schmerz, Taubheit oder Kribbeln in den Händen, Schmerz, der schlimmer wird, wenn du weitermachst, Schwindel oder ein Schlag auf den Kopf mit irgendwelchen anhaltenden Symptomen. Nackenbewegungen und Contact Rolls verdienen besondere Vorsicht; lerne sie langsam mit einem gepolsterten Prop.","Diese App vermittelt Technik, keine medizinische Versorgung. Schwangerschaft, kürzliche Verletzungen, Gelenkerkrankungen und alles, was dir Sorgen macht, sind Gründe, vor zusätzlicher Belastung eine qualifizierte Fachperson zu fragen. Feuerperformance ist eine eigene Disziplin mit eigener Sicherheitsschulung; SynthFlow unterrichtet sie nicht."]},"warm-up":{"title":"Warum Aufwärmen beim Prop-Training wichtig ist","summary":"Zwei bis fünf Minuten Mobilität für Handgelenke, Arme, Schultern und Hüften machen Spins flüssiger und schonen deine Gelenke.","imageAlt":"3D-Figur macht langsame Handgelenkskreise mit nach vorn gestreckten Armen","body":["Flow-Training sieht sanft aus, verlangt aber einigen Gelenken viel ab. Jonglieren wiederholt denselben Wurf tausende Male; Staff-Spinning rollt die Handgelenke durch ihren vollen Bewegungsumfang; Hooping bewegt Wirbelsäule und Hüften bei jedem Orbit. Warmes Gewebe verträgt diese Wiederholung viel besser als kaltes.","Ein gutes Flow-Aufwärmen ist kurz und spezifisch. Handgelenkskreise in beide Richtungen bereiten die Gelenke vor, die die meiste Arbeit leisten. Armkreise und Schulterrollen wecken die Rotatorenmanschette und die Schulterblätter, die die Ebene jedes Spins kontrollieren. Hüftkreise und Rumpfdrehungen sind beim Hooping am wichtigsten. Halbe Nackenkreise, niemals volle Rollen, lösen Spannung vom Hochschauen auf ein Muster.","Bewege dich langsam und im Takt. Die Aufwärm-Schritte in SynthFlow werden wie alles andere gezählt, in entspanntem Tempo, sodass die ersten Minuten einer Session auch dein Timing stimmen. Wenn die Props herauskommen, bewegst du dich schon mit der Musik.","Beende das Aufwärmen mit dem Prop bei halber Geschwindigkeit. Ein paar langsame Würfe, ein lockerer Front Spin oder ein großer, langsamer Hoop-Orbit verbinden die Mobilitätsarbeit mit der Bewegung, die du gleich übst, und sie sagen dir, wie sich dein Körper heute anfühlt.","Aufwärmen ist auch ein mentaler Übergang. Dieselben drei Minuten zu Beginn jeder Session werden zum Signal, dass das Training begonnen hat. An vollen Tagen ist das Aufwärmen manchmal das ganze Training, und das zählt trotzdem."]},"anatomy-basics":{"title":"Der Körper hinter den Props","summary":"Unterarme greifen und lösen, Schultern steuern die Ebene, der Core hält dich still: eine einfache Karte für Flow.","imageAlt":"3D-Figur hoopet an der Taille mit entspanntem Oberkörper","body":["Du musst keine Anatomie kennen, um zu jonglieren, aber eine einfache Karte hilft dir zu verstehen, was ermüdet, was du aufwärmen und was du ausruhen solltest. Der Bereich Muskeln in Lernen hat ein interaktives Modell; dieser Artikel ist die kurze Tour.","Die Unterarme leisten die meiste Feinarbeit. Muskeln auf der Handflächenseite schließen die Finger und beugen das Handgelenk; Muskeln auf der Rückseite des Unterarms öffnen die Finger und strecken das Handgelenk. Fangen und Loslassen, einen Staff greifen und rollen lassen, all das passiert hier. Unterarmmüdigkeit ist das häufigste Gefühl nach einer langen Session, und deshalb ist entspannter Griff so ein häufiger Cue.","Die Schultern steuern. Die Deltoideus-Muskeln heben die Arme; die Rotatorenmanschette, vier kleine Muskeln um das Gelenk, hält den Oberarm während der Bewegung zentriert. Muskeln um die Schulterblätter halten das ganze System stabil. Wenn ein Staff aus seiner Ebene driftet, liegt die Ursache oft in der Schulter, nicht in der Hand.","Der Core hält dich ruhig. Beim Jonglieren verhindert ein stiller Oberkörper, dass das Muster wandert. Beim Hooping treiben Bauch- und Rückenmuskeln den Hoop mit kleinen Vor- und Zurück-Impulsen an. Hüften und Beine sind deine Basis: weiche Knie absorbieren Bewegung und lassen dich das Gewicht verlagern, ohne das Prop zu stören.","Auch Augen und Innenohr zählen. Jonglieren trainiert dich, die Scheitelpunkte zu beobachten, nicht die Hände; Spinning trainiert dein Gleichgewicht. Kurze Sessions mit Pausen lassen beide sich anpassen, ohne dass dir schwindelig wird. Behandle diese Karte als Grundwissen, nicht als Diagnose, und suche bei Schmerzen, die nicht abklingen, eine Fachperson auf."]},"biomechanics-safety":{"title":"Handgelenke, Schultern und wiederholte Belastung","summary":"Entspannter Griff, neutrale Handgelenke und allmähliche Steigerung halten die Gelenke, die alle Arbeit leisten, zufrieden.","imageAlt":"3D-Figur spinnt einen Staff mit einer Hand über dem Handrücken","body":["Flow-Verletzungen sind selten dramatisch. Sie sind fast immer Überlastung: zu viele Wiederholungen, zu viel Griff, zu wenig Ruhe. Die gute Nachricht: Dieselben wenigen Gewohnheiten verhindern die meisten davon.","Locker den Griff. Ein Jonglierball braucht nur so viel Druck, dass er in der Hand bleibt; ein Staff braucht einen lockeren Fingerring, in dem er rollen kann. Zudrücken ermüdet die Unterarmmuskeln und belastet die Sehnen am Ellbogen. Wenn deine Knöchel weiß werden oder die Unterarme nach ein paar Minuten brennen, lockere und senke das Tempo.","Halte die Handgelenke möglichst nah an neutral. Spinning führt die Handgelenke durch große Bewegungsumfänge, was in Maßen in Ordnung ist. Sie lange am Ende ihres Bereichs zu halten oder ein steifes Handgelenk zum Drehen zu zwingen, reizt sie. Lass Ellbogen und Schulter die Bewegung mit tragen.","Lass die Schultern arbeiten, aber nicht hochziehen. Große Kreise kommen aus dem Schultergelenk; eine hochgezogene Schulter klemmt und ermüdet schnell. Prüfe im Spiegel oder im Kameramodus, dass deine Schultern unten bleiben, besonders bei Überkopf-Bewegungen wie Helicopter und Lasso.","Steigere das Volumen allmählich. Wenn du normalerweise zwanzig Minuten übst, spring nicht auf zwei Stunden, weil ein Festival kommt. Erhöhe die Gesamtzeit jede Woche um einen moderaten Betrag und halte mindestens einen leichten Tag ein. Wechsle Props, um die Last zu verteilen: Hoop-Arbeit entlastet die Unterarme, die Jonglieren ermüdet.","Schmerz, der innerhalb eines Tages nachlässt, ist normale Anpassung; Schmerz, der bleibt, wächst oder mit Taubheit kommt, ist es nicht. Ruhe dich aus, reduziere das Volumen und suche professionellen Rat, wenn er anhält. Das ist Bildung, keine medizinische Beratung."]},"choosing-props":{"title":"Die ersten Props auswählen","summary":"Beanbags zum Jonglieren, ein leichter gepolsterter Staff und ein großer Erwachsenen-Hoop machen die ersten Wochen viel einfacher.","imageAlt":"3D-Figur spinnt einen Hoop um eine Hand","body":["Gute Anfänger-Props machen das Lernen schneller und weniger frustrierend. Du brauchst keine teure Ausrüstung, aber ein paar Entscheidungen sind wichtig.","Beginne beim Jonglieren mit drei Beanbag-Bällen von etwa 60 bis 130 Gramm. Beanbags springen oder rollen nicht weg, wenn sie fallen, was viel Hinterherlaufen spart. Sie sollten bequem in deine Handfläche passen. Stage Balls, die größer sind, und springende Silikonbälle sind für später. Gleiche Farben helfen dir, das Muster zu sehen; drei verschiedene Farben helfen dir, einzelne Bälle zu verfolgen, wenn du Siteswaps lernst.","Für Staff ist ein Anfänger-Spin-Staff meist etwa 1,2 bis 1,5 Meter lang, leicht, mit gepolsterten oder Gummi-Enden. Als grobe Orientierung sollte er zwischen Brust und Schulter reichen, wenn er aufrecht steht. Ein längerer, schwererer Staff dreht langsamer und flüssiger, sobald du die Grundlagen hast, aber er ist am Anfang schwieriger und tut mehr weh, wenn er dich trifft. Ein Griff in der Mitte hilft.","Beginne beim Hoop größer und schwerer, als du denkst. Ein Erwachsenen-Anfänger-Hoop reicht typischerweise etwa zwischen Taille und Brust, wenn er auf dem Boden steht. Größere Hoops drehen langsamer und geben dir Zeit, den Rhythmus für Waist Hooping zu finden. Kleinere, leichtere Hoops eignen sich für schnelle Off-Body-Tricks, sobald du dich wohlfühlst.","Was auch immer du wählst, stelle sicher, dass der Tempo-Bereich der Bewegung zum Prop passt. Schwerere Props mögen meist niedrigere Tempi. Wenn sich der komfortable Bereich der App mit deinem Prop gehetzt anfühlt, setze dein eigenes Tempo im Builder; die Counts folgen."]},"practice-at-home":{"title":"Zu Hause und im Park üben","summary":"Kurze tägliche Sessions, ein freier Platz, eine Bett- oder Sofakante zum Auffangen von Drops und eine Park-Jam, wenn du kannst.","imageAlt":"3D-Figur schüttelt zwischen Trainingsrunden die Arme aus","body":["Die meisten Flow-Artists lernen zu Hause, ein paar Minuten auf einmal. Ein wenig Vorbereitung macht Heimtraining leichter zu beginnen und leichter durchzuhalten.","Finde deinen Platz. Beim Jonglieren bedeutet Stehen vor einem Bett oder Sofa, dass fallende Bälle auf Taillenhöhe landen, statt unter Möbel zu rollen, und es hält dich auch davon ab, nach vorn zu laufen. Für Staff und Hoop finde den größten freien Platz, den du hast, prüfe die Decke und räume alles Zerbrechliche weg. Ein Garten oder Park ist besser für große Spins.","Halte die Props sichtbar. Bälle auf dem Schreibtisch werden während Calls und Teepausen jongliert; ein Hoop an der Tür wird benutzt. Je weniger Aufwand es braucht anzufangen, desto öfter wirst du es tun. Eine Fünf-Minuten-Routine zählt, und mehrere kurze Sessions am Tag summieren sich schnell.","Nutze die App als Struktur. Wähle eine Routine oder lass dir vom Assistenten eine vorschlagen, spiele sie durch und protokolliere deinen Aufwand. Kurze Programme wie Zero to Cascade geben jeder Woche ein klares Ziel, damit du nicht zwischen Tricks umhertreibst.","Übe mit anderen, wenn du kannst. Jonglierclubs, Zirkusschulen und Park-Flow-Jams gibt es in vielen Städten. Jemandem zuzusehen, der einen Schritt voraus ist, löst oft etwas, das ein Tutorial nicht konnte, und jemandem etwas beizubringen, der einen Schritt hinter dir ist, macht deine eigene Technik klarer. Bring deine Props mit, frag, woran die Leute arbeiten, und teile, was dir die Counts beigebracht haben."]},"learning-with-the-app":{"title":"Lernen mit dem 3D-Coach","summary":"Verlangsame es, spiegle es, schalte Ghost und Trails ein, wechsle die Kamera und nutze den Kameramodus für Feedback.","imageAlt":"3D-Figur führt eine Staff-Isolation aus, mit einem Trail, der den Weg zeigt","body":["Jede Bewegung in SynthFlow wird in 3D von derselben Uhr wie die Musik animiert, sodass die Figur immer genau auf dem Beat ist. Gut genutzt ist der Viewer ein geduldiger Lehrer, der nie müde wird, dir denselben Wurf zu zeigen.","Verlangsame es zuerst. Die Progressionsleiter bei jeder Bewegung beginnt mit langsamen und teilweisen Versionen, dann nur Hände, dann die vollständige Bewegung auf dem Beat. Halbes Tempo bewahrt die Timing-Beziehungen und gibt deinen Augen Zeit zu folgen.","Spiegle die Figur, wenn du besser lernst, wenn du einem Lehrer gegenüberstehst, und wechsle die Kamera, wenn eine Ansicht etwas verdeckt. Seitenansichten zeigen Staff-Neigung und Wurf-Drift; Draufsichten zeigen Hoop-Ebenen und Helikopter-Bahnen. Die Trails zeichnen auf, wo jeder Prop gewesen ist, was einen Blur in eine Form verwandelt, die du studieren kannst. Der Ghost zeigt, wo der Prop beim nächsten Beat sein wird.","Achte auf die häufigen Fehler. Jede Bewegung kann ihre typischen Fehler zeigen, wie nach vorne driften, ungleiche Höhen oder hetzen, absichtlich falsch an der Figur vorgeführt, mit dem Cue, der sie behebt. Einen Fehler am Modell zu erkennen, macht es viel leichter, ihn im eigenen Körper zu spüren.","Der Kameramodus gibt dir Feedback über dich. Mit Erlaubnis verfolgt er deine Hände und deinen Körper während du übst und vergleicht dein Timing mit dem Beat. Die Verarbeitung findet auf deinem Gerät statt. Es ist nicht perfekt, und gutes Licht hilft, aber selbst grobes Feedback darüber, ob du zu früh oder zu spät bist, ist wertvoll.","Schließe den Viewer schließlich manchmal. Übe nur mit Musik und vertraue den Counts. Das Ziel ist eine Bewegung, die du ausführen kannst, ohne überhaupt etwas anzusehen."]},"music-for-flow":{"title":"Musik finden, die passt","summary":"Gemessene Tempi, Halb- und Doppelzeit, generierte Percussion und deine eigenen Tracks halten die Counts ehrlich.","imageAlt":"3D-Figur hoopt auf Brusthöhe mit erhobenen Armen","body":["Musik verwandelt Übung in Flow, aber nur, wenn der Beat in der Musik der Beat in den Counts ist. Ein Track mit 118 BPM unter einer 120-BPM-Routine driftet innerhalb einer Minute auseinander, und du kämpfst am Ende gegen die Musik, statt sie zu reiten.","SynthFlows mitgelieferte Tracks haben gemessene Tempi und Downbeats, sodass der Player jeden Schritt auf der „Eins“ der Musik starten und die Counts ausgerichtet halten kann. Der Builder listet zuerst Tracks auf, die zum Tempo eines Abschnitts passen, einschließlich Tracks mit halbem oder doppeltem Tempo: Ein 140-BPM-Track trägt einen 70-BPM-Hoop-Schritt problemlos.","Generierte Percussion funktioniert bei jedem Tempo. Wähle ein Kit für einen Abschnitt, und der Player synthetisiert einen Beat, der genau passt, egal ob du eine Tempo-Leiter oder eine langsame Drill machst. Es ist auch die beste Option, wenn du den Puls willst, ohne dass eine Melodie deine Aufmerksamkeit zieht.","Du kannst Tracks von deinem eigenen Gerät analysieren. Die App schätzt Tempo und Downbeat und lässt dich sie durch Mitklopfen überprüfen. Tracks mit einem gleichmäßigen elektronischen oder akustischen Puls funktionieren am besten; Musik mit Tempoänderungen, Rubato oder langen Intros ist schwerer zu messen und schwerer zum Üben.","Video-Streaming ist während gezählter Übung ausgeschaltet, weil sein Timing nicht präzise kontrolliert werden kann. Nutze es stattdessen für Warm-ups oder freies Spielen, wo nichts übereinstimmen muss."]},"plateaus":{"title":"Plateaus und die lange Mitte","summary":"Jeder Flow-Artist erlebt Wochen, in denen nichts besser wird; ändere die Drill, das Tempo oder den Prop, bevor du das Ziel änderst.","imageAlt":"3D-Figur jongliert Mills Mess mit gekreuzten Armen","body":["Der Anfang des Flow ist wunderbar: jede Session etwas Neues. Dann, oft etwa zu der Zeit, in der du eine stabile Cascade jonglieren oder einen Hoop unbegrenzt oben halten kannst, scheint der Fortschritt zu stoppen. Diese lange Mitte ist der Punkt, an dem die meisten aufhören, und wo das interessanteste Lernen stattfindet.","Plateaus sind meistens Konsolidierung. Dein Nervensystem reorganisiert die Bewegung, damit sie weniger Aufmerksamkeit braucht, was sich nicht als neue Tricks zeigt. Oft taucht eine Fähigkeit, die sich zwei Wochen festgefahren anfühlte, plötzlich eines Morgens auf. Übe weiter durch den flachen Teil hindurch.","Ändere die Drill, nicht das Ziel. Wenn die Cascade nicht schneller wird, übe sie bei niedrigerem Tempo mit perfekten Peaks, dann mit den Augen auf einem Punkt über dem Muster, dann nur mit einer Hand. Wenn eine Staff-Bewegung nicht kommt, teile sie in ihre Hälften und drille jede auf den Beat. Neue Drills geben deinem Gehirn neue Informationen über dieselbe Fähigkeit.","Cross-Training. Einen zweiten Prop zu lernen, entsperrt oft den ersten. Hooping verbessert den Rhythmus hinter dem Jonglieren; Staff-Arbeit lehrt die Ebenen, die Hoop-Tricks sauber machen. Der Rewards-Baum für jede Kunst ist unabhängig, also kostet Vielfalt nie Fortschritt.","Sei freundlich zu dir. Vergleiche dich mit dem letzten Monat, nicht mit Performern online, die zehn Jahre geübt haben. Die Progress-Seite führt eine ehrliche Aufzeichnung von Minuten, Top-Tempi und gemeisterten Bewegungen. In einer flachen Woche schau sie an und sieh, wie weit die Linie bereits geklettert ist."]},"history-of-juggling":{"title":"Eine kurze Geschichte des Jonglierens","summary":"Von einem ägyptischen Grabmal über mittelalterliche Jongleure, Varietétheater und moderne Mathematik.","imageAlt":"3D-Figur jongliert eine Three-Ball-Shower im Kreis","body":["Jonglieren ist sehr alt. Eines der frühesten bekannten Bilder ist eine Wandmalerei in einem Grab des Mittleren Reiches in Beni Hasan in Ägypten, etwa viertausend Jahre alt, die Frauen beim Ballwerfen zeigt. Berichte und Bilder aus China, Griechenland, Rom und dem Pazifik deuten darauf hin, dass Menschen in vielen Kulturen zum Werfen und Fangen zur Schau und zum Spiel gefunden haben.","Im mittelalterlichen Europa beschrieb das Wort Jongleur, von dem „Juggler“ stammt, reisende Unterhalter, die sangen, Geschichten erzählten, Akrobatik vorführten und Gegenstände warfen. Jonglieren war eine Fähigkeit unter vielen, Teil des Werkzeugkastens eines Performers statt eine eigene Kunst.","Die Varietétheater und Zirkusse des neunzehnten und frühen zwanzigsten Jahrhunderts machten Jonglieren zur Hauptattraktion. Performer spezialisierten sich: Gentleman-Jongleure mit Hüten und Stöcken, Club-Jongleure und Numbers-Jongleure, die zu sieben, acht und mehr Bällen strebten. Enrico Rastelli im frühen zwanzigsten Jahrhundert wird noch heute oft als einer der Größten genannt.","Ab den 1970er Jahren wuchs eine Hobby-Jonglierkultur rund um Clubs, Festivals und Conventions, in der Menschen Tricks frei teilten. Die Mathematik kam in den 1980er Jahren dazu, als die Siteswap-Notation Jongleuren eine Möglichkeit gab, Muster als Zahlen zu schreiben, was zu neuen Tricks führte, die auf dem Papier entdeckt wurden, bevor sie jemand warf.","Heute liegt Jonglieren am Treffpunkt von Zirkus, Sport, Tanz und Mathematik. Manche Jongleure treten in Numbers und Ausdauer an, andere führen Choreografien zu Musik auf, andere erkunden Muster um ihrer selbst willen. Jeder Weg beginnt mit demselben Austausch von zwei Bällen, den du diese Woche lernen kannst."]},"history-of-staff":{"title":"Staff-Spinning: von der Waffe zum Flow","summary":"Kampfkunst-Staffs, Baton Twirling und Feuerperformance haben alle den modernen Spin-Staff genährt.","imageAlt":"3D-Figur führt einen Staff-Butterfly hinter den Schultern aus","body":["Ein Staff ist eines der ältesten Werkzeuge überhaupt, und einen zu spinnen ist eine alte Fähigkeit. Viele Kampftraditionen trainieren mit einem langen Staff, darunter der okinawanische Bō, das chinesische Gun und der europäische Quarterstaff-Kampf, und ihre Drills umfassen schnelle Spins und Handwechsel sowohl zur Verteidigung als auch zur Schau.","Performance-Spinning hat auch andere Wurzeln. Baton Twirling entwickelte sich im zwanzigsten Jahrhundert zu einer Wettkampfdisziplin, mit Würfen, Rolls und Spins, die Spinner noch heute borgen. Theater, Paraden und Straßenperformance auf der ganzen Welt nutzten gedrehte Stöcke und Stangen lange bevor jemand es Flow nannte.","Die moderne Flow-Staff-Szene entstand im späten zwanzigsten Jahrhundert zusammen mit Feuerperformance und Festival-Kultur. Feuer-Staffs mit Dochten an beiden Enden machten das Spinnen im Dunkeln sichtbar und drängten die Kunst zu fließenden, kontinuierlichen Bewegungen statt Schlägen. LED-Staffs brachten dieselben Visuals später in den Innenraum.","Etwa zur selben Zeit begannen Flow-Artists, das Spinnen mit gemeinsamer Theorie zu beschreiben: Ebenen, Spin und Antispin, Isolations, Timing und Richtung. Vieles davon wurde in der Poi-Community entwickelt und auf Staff, Hoop und andere Props übertragen, weshalb dieselben Begriffe in dieser App überall auftauchen.","Contact Staff, bei dem der Staff über den Körper rollt statt gegriffen zu werden, entwickelte sich zu einem eigenen Stil mit Rolls über Nacken, Schultern und Arme. Heute reicht Staff-Spinning von martialischer Demonstration bis zu langsamem, meditativem Contact Flow, alles aufgebaut auf demselben ersten Wheel Spin."]},"history-of-hoop":{"title":"Der Hoop: vom antiken Spielzeug zur Flow-Kunst","summary":"Hoops sind seit Jahrtausenden Spielzeug und Werkzeug; ein Trend der 1950er und ein Festival-Revival machten Hoop Dance zur Kunst.","imageAlt":"3D-Figur, die einen spinnenden Hoop am Körper hochführt","body":["Hoops gehören zu den ältesten Spielzeugen. Kinder im alten Ägypten, in Griechenland und Rom werden beschrieben oder abgebildet, wie sie Hoops mit Stöcken rollen und um den Körper spinnen, und Hoop-Spiele tauchen seitdem in vielen Kulturen auf.","Hoops tragen in manchen Traditionen auch tiefe kulturelle Bedeutung. Der Hoop Dance, der in vielen Native-American-Communities aufgeführt wird, nutzt mehrere Hoops, um Formen wie Tiere und die Erde zu bilden und Geschichten durch Bewegung zu erzählen. Er ist eine lebendige Tradition für sich, verschieden von der modernen Flow-Szene, und es lohnt sich, von ihren eigenen Praktizierenden darüber zu lernen.","Der Plastik-Hula-Hoop-Trend der späten 1950er, angetrieben von massenproduzierten Hoops in den Vereinigten Staaten, brachte fast über Nacht einen Hoop in Millionen Haushalte. Jahrzehntelang danach galt der Hoop meist als Kinderspielzeug und Fitness-Gadget.","Ab den späten 1990ern und 2000ern begannen erwachsene Hooper auf Festivals und in Online-Communities, den Hoop als Tanzpartner zu behandeln. Größere, schwerere handgemachte Hoops machten On-Body-Hooping für Erwachsene einfacher, während kleinere Hoops schnelle Off-Body-Tricks eröffneten. Geteilte Videos verbreiteten Vokabular wie Isolations, Wedgies und Escalators weit über eine einzelne Stadt hinaus.","Moderner Hoop Dance leiht sich Theorie von Staff und Poi und Rhythmus aus jeder Art von Musik. Er ist zugänglich, freudvoll und tief: Ein Anfänger findet den Hüftrhythmus an einem Tag, und ein Experte kann Jahre damit verbringen, eine einzige Isolation zu verfeinern."]},"fire-and-led":{"title":"Feuer-, LED- und Performance-Props","summary":"Performance-Props verändern Gewicht, Geschwindigkeit und Risiko; lerne jede Bewegung zuerst mit Übungs-Props und trainiere Feuer separat.","imageAlt":"3D-Figur, die einen Hoop flach über dem Kopf wie ein Lasso kreisen lässt","body":["Einen Feuer-Staff oder einen LED-Hoop bei Nacht zu sehen, ist oft das, was Menschen zum Flow bringt. Performance-Props sind wunderbar, aber sie sind nicht dasselbe wie Übungs-Props, und der Umstieg auf sie verdient einen Plan.","LED-Props sind wegen Batterien und Elektronik meist schwerer als ihre Übungsversionen. Das verändert den Impuls: Spins tragen weiter, Throws fühlen sich anders an, und die Handgelenke arbeiten härter. Lerne jede Bewegung zuerst mit deinem Übungs-Prop und rechne dann mit einer kurzen Umstellungsphase auf LED. Senke das Tempo für die ersten Sessions.","Feuerperformance ist eine eigene Disziplin. Umgang mit Brennstoff, sichere Spin-Bereiche, Safety-Spotters mit Feuerlöschdecken, geeignete Kleidung und lokale Regeln sind alle wichtig, und man lernt sie am besten persönlich von erfahrenen Feuer-Performern. SynthFlow unterrichtet kein Feuer, und nichts in der App sollte mit brennenden Props geübt werden.","Eine gute Regel, die in vielen Flow-Communities gilt, ist: Führe eine Bewegung erst dann mit einem Performance-Prop aus, wenn du sie zuverlässig viele Male hintereinander mit einem Übungs-Prop kannst. Unter Lichtern oder Flammen ist kein Raum für Experimente.","Performance verändert auch, wie du sequenzierst. Publikum liest große Ebenen, saubere Übergänge und klare Momente der Stille. Baue Performance-Routinen im Builder wie jede andere, sieh sie dir in der Vorschau an und probt sie jedes Mal zur selben Musik, damit die Counts zur Choreografie werden."]}}`),r=JSON.parse(`{"the-day-the-cascade-clicked":{"title":"Der Tag, an dem die Cascade klickte","summary":"Drei Wochen lang Bällen hinterherjagen endeten in dem Moment, als ich aufhörte, meine Hände zu beobachten, und anfing zu zählen.","body":["Drei Wochen lang hielt meine Drei-Ball-Cascade genau vier Würfe. Rechts, links, rechts, und dann war der dritte Ball irgendwo hinter dem Sofa. Ich schaute Videos, ich wurde langsamer, ich wurde schneller. Ich stellte mich vors Bett, wie jedes Tutorial sagt. Nichts änderte sich, außer meinem Vokabular.","Die Lösung, als sie kam, war peinlich einfach. Ich legte einen Track mit 90 BPM auf und sagte die Counts laut: eins, zwei, drei, vier, ein Wurf auf jeden Beat. Plötzlich hatten die Würfe einen Ort, an dem sie sein mussten. Statt zu werfen, wenn die Hand sich bereit fühlte, was bedeutete, wann immer die Panik es befahl, wartete jeder Wurf auf seinen Beat. Das Muster wurde langsamer, höher und ruhiger.","Die zweite Lösung war, wohin ich schaute. Ich hatte auf meine Hände gestarrt, was so ist, als würde man ein Buch lesen, indem man seine Augenlider beobachtet. Als ich meinen Blick zu den Peaks hob, den zwei Punkten oben an den Bögen, fingen meine Hände an, von selbst zu fangen. Die Peaks sagten mir, ob die Würfe gleichmäßig waren; die Hände brauchten keine Aufsicht.","Zwölf Würfe wurden zwanzig, dann fünfzig. Eines Abends jonglierte ich einen ganzen Acht-Takt-Step ohne Drop durch und grinste wie ein Idiot an die Decke. Die App nannte es einen Clean Run. Ich nannte es das erste Mal, dass sich Jonglieren wie Musik anfühlte statt wie ein Kampf.","Wenn du bei vier Würfen feststeckst, probiere, was bei mir funktioniert hat: laut zählen, auf den Beat werfen, auf die Peaks schauen. Und drop ohne Drama. Der Boden ist der Ort, an dem jede Cascade beginnt."]},"why-we-count-in-bars":{"title":"Warum wir in Takten zählen, nicht in Sekunden","summary":"Eine vierzigsekündige Hold ergibt Sinn für eine Dehnung; ein Jongliermuster lebt auf einem Beat, also messen wir Übung in Takten.","body":["Als wir anfingen, SynthFlow zu bauen, war die erste große Entscheidung, wie man einen Routine-Step misst. Unsere Schwester-App SynthYoga zählt Holds in Sekunden und Atemzügen. Das funktioniert für eine Pose, die du hältst. Es funktioniert nicht für ein Muster, das sich auf einem Beat wiederholt.","Ein Jonglierwurf, eine Staff-Halbdrehung und eine Hoop-Umlaufbahn sind alle Zyklen. Wenn die Musik mit 100 BPM läuft und deine Cascade mit 103, jonglierst du nicht zur Musik; du jonglierst daneben, und innerhalb einer Minute bist du einen Beat hinterher. Steps in Takten bei einem Tempo zu messen bedeutet, dass Musik, Counts, die 3D-Figur und der nächste Step alle auf demselben Downbeat starten.","Takte machen Fortschritt auch konkret. „Jongliere eine Minute“ ist vage: eine Minute wovon, bei welcher Geschwindigkeit? „Acht Takte Cascade bei 96 BPM“ ist eine spezifische, wiederholbare Herausforderung. Wenn du sie sauber schaffst, kann die nächste Session 104 verlangen. So funktionieren Tempo-Leitern, und deshalb hängt Mastery in der App von Clean Runs ab, nicht nur von Zeit.","Es brauchte ernsthaftes Engineering. Jede Animation wird von derselben Audiouhr wie die Musik angetrieben und im Voraus geplant, damit nichts stockt. Mitgelieferte Tracks haben gemessene Tempi und Downbeats. Generierte Percussion füllt jedes Tempo, das du wählst. Tracks von deinem Gerät werden analysiert und mit einem Tap-Test geprüft. Streaming-Video ist im gezählten Üben ausgeschaltet, weil wir es nicht auf dem Beat halten können.","Das Ergebnis ist, dass der Beat zum Lehrer wird. Wenn du driftest, hörst du es. Wenn du einrastest, fühlst du es. Das Zählen in Takten entpuppte sich als die wichtigste Designentscheidung, die wir getroffen haben."]},"staff-hit-me-in-the-head":{"title":"Der Staff traf mich am Kopf (und andere Lektionen)","summary":"Jeder Staff-Spinner wird mal bonkt; Polsterung, Ebenen und Geduld machen aus den Bonks Fortschritt.","body":["Meine erste Acht endete damit, dass der Staff von meinem Schädel abprallte und der Hund den Raum verließ. Meine zweite endete genauso, minus Hund. Wenn du Staff lernst, wirst du getroffen. Die Frage ist, wie hart, und was du daraus lernst.","Lektion eins: Polsterung ist keine Feigheit. Ein Übungs-Staff mit weichen Enden machte aus Bonks Schulterzucken. Schulterzucken ist wichtig, denn Angst lässt dich zusammenzucken, und ein zusammenzuckendes Handgelenk zieht den Staff aus seiner Ebene, was den nächsten Bonk verursacht.","Lektion zwei: Die meisten Treffer kommen von gekippten Ebenen. Als ich mich von der Seite filmte, konnte ich sehen, wie der Staff sich bei jeder Drehung oben zu meinem Gesicht neigte. Meine Handgelenke rollten nach innen. Das Ebenen-Overlay im 3D-Viewer zeigte die saubere Version: der Staff in einer flachen Fläche neben dem Körper, nie nach innen geneigt. Das Handgelenk zu korrigieren, korrigierte die Bonks.","Lektion drei: Langsam und gezählt schlägt schnell und hoffnungsvoll. Ich senkte das Tempo auf das untere Ende des Bereichs der Acht und zählte „rechte Seite, linke Seite“ mit der Musik. Bei diesem Tempo konnte ich den Handwechsel spüren und die Ebene flach halten. Eine Woche später konnte ich wieder hochgehen.","Lektion vier: Lache. Staff-Spinning ist lächerlich und wunderbar. Die Bonks gehören zur Geschichte, die jeder in der Szene teilt. Trag einen Hut, wenn du musst, räum die Deckenlichter frei und spinne weiter."]},"hooping-for-people-who-cant-hoop":{"title":"Hooping für Menschen, die denken, sie können nicht hoopen","summary":"Die meisten Erwachsenen, die „nicht hoopen können“, hatten einen reifengroßen Spielzeug-Hoop; ein größerer Reifen und ein Vor-und-zurück-Impuls lösen das meiste.","body":["„Ich kann nicht hoopen“ hören Hoop-Lehrer ständig, meist von jemandem, der es zuletzt mit einem Kinder-Spielzeugreifen versucht hat. Kleine, leichte Reifen drehen schnell und fallen schnell. Sie verlangen schnelle, hektische Hüften. Erwachsene mit einem Reifen in Erwachsenengröße finden es oft viel handhabbarer.","Fang groß an. Ein Reifen, der auf dem Boden stehend etwa zwischen Taille und Brust reicht, dreht langsam genug, dass du den Rhythmus spüren kannst. Schwerere Reifen tragen auch mehr Schwung. Du kannst später kleiner gehen für Tempo und Off-Body-Tricks.","Impuls, nicht Kreis. Der häufigste Fehler ist der Versuch, große Kreise mit den Hüften zu machen. Waist Hooping ist meist ein kleines Vor-und-zurück-Wippen oder ein Seit-zu-Seit, im Takt mit dem Reifen. Ein Fuß leicht vorne hilft. Der Reifen berührt deine Vorder- und Rückseite; du schiebst sanft, wenn er herumkommt.","Zähl mit. Ein entspanntes Tempo, eine Umlaufbahn pro Beat, gibt deinem Körper einen Rhythmus, in den er sich einfinden kann. Die App startet Waist Hooping langsam und lässt dich dann steigern. Wenn der Reifen sinkt, gib etwas mehr Tempo in deinen Impuls, nicht eine größere Bewegung.","Erwarte, dass er in ein paar Sessions oft fällt und dann plötzlich nicht mehr. Hooping ist eine dieser Fähigkeiten, die klick machen. Wenn es klickt, wartet eine ganze Welt von On-Body- und Off-Body-Flow, und vieles davon braucht nicht mal die Taille."]},"unlocking-is-not-a-race":{"title":"Freischalten ist kein Wettrennen","summary":"Der Belohnungsbaum öffnet schwierigere Bewegungen, während du ihre Grundlagen meisterst; der Punkt sind die Grundlagen.","body":["SynthFlows Belohnungen sind Bewegungen. Meistere die Cascade und die Reverse Cascade öffnet sich; meistere den Front Spin und die Figure-8 erscheint. Es ist befriedigend, den Baum aufleuchten zu sehen, und wir haben es genau so designt. Aber jedes Freischalt-System hat eine Falle, und es lohnt sich, sie zu benennen.","Die Falle ist, Meisterschaft als abzuhakendes Kästchen zu behandeln. Du kannst an einem guten Tag technisch die Clean Runs für eine Bewegung loggen, die nächste freischalten und mit einer Grundlage weitermachen, die nur funktioniert, wenn alles gut läuft. Dann fühlen sich die schwierigeren Bewegungen unmöglich an, weil sie davon ausgehen, dass die Grundlage funktioniert, wenn etwas schiefgeht.","Meisterschaft im Flow bedeutet, dass die Bewegung Ablenkung übersteht: etwas Müdigkeit, ein anderes Tempo, jemand, der vorbeigeht. Deshalb verlangt Meisterschaft Clean Runs über mehrere Sessions, nicht nur in einer. Und deshalb empfehlen wir, regelmäßig zu gemeisterten Bewegungen zurückzukehren. Die Cascade ist kein Level, das du abschließt; sie ist der Boden, auf dem der ganze Jonglierbaum steht.","Gesperrte Bewegungen haben trotzdem Seiten. Du kannst über sie lesen, sie in 3D anschauen und sehen, was sie brauchen. Vorausschauen motiviert. Vorausüben ohne die Grundlagen ist meist frustrierend.","Genieß also die Unlocks, aber miss dich daran, wie leicht sich deine ältesten Bewegungen anfühlen. Wenn die Cascade langweilig ist, bist du bereit für Mills Mess. Wenn Mills Mess langweilig ist, hat der Baum mehr zu bieten."]},"practice-in-ten-minutes":{"title":"Eine echte Practice in zehn Minuten","summary":"Warm-up, eine Fokus-Bewegung, ein Link, ein kurzer Tempo-Anstieg und ein Cool-down: zehn Minuten, jeden Tag.","body":["Der häufigste Grund, den Leute fürs Nicht-Üben nennen, ist Zeit. Die Wahrheit ist, dass Flow-Skills brillant auf kurze, häufige Sessions reagieren. Hier ist die Zehn-Minuten-Form, die wir selbst nutzen.","Minute eins bis zwei: Warm-up. Handgelenkskreise, Armkreise, Schulterrollen, ein paar Hüftkreise, wenn du hoopst. Gezählt, in entspanntem Tempo, damit dein Timing mit deinen Gelenken aufwacht.","Minute drei bis fünf: deine Fokus-Bewegung. Eine Bewegung, an der du arbeitest, in einem Tempo, das du sauber schaffst. Mehrere kurze gezählte Steps statt einem langen, mit einem Atemzug dazwischen.","Minute sechs bis sieben: ein Link. Kombiniere die Fokus-Bewegung mit etwas, in das sie hinein- oder aus dem sie herausfließt. Cascade zu Reverse Cascade. Front Spin zu Figure-8. Waist zu Chest. Links sind das, was Practice wie Flow statt Drill wirken lässt.","Minute acht bis neun: ein kleiner Tempo-Anstieg. Zwei oder drei Stufen, ein paar BPM jeweils, aufhören bevor die Form bricht. End auf einer sauberen Stufe.","Minute zehn: Cool-down. Eine langsame, leichte Bewegung oder eine kurze Pause. Log deine Anstrengung. Fertig.","Zehn Minuten am Tag sind über eine Stunde fokussierte Practice pro Woche, verteilt auf die Art, die Koordination am liebsten mag. Der Practice Wizard baut Sessions dieser Größe, wenn du ihm sagst, dass du wenig Zeit hast, und die eingebauten kurzen Routinen folgen derselben Form."]},"antispin-broke-my-brain":{"title":"Antispin hat mein Gehirn zerstört (für eine Woche)","summary":"Den Staff gegen den Kreis der Hand zu drehen fühlt sich unmöglich an, bis die Counts jedem Petal einen Beat geben.","body":["Antispin ist der Punkt, an dem sich Staff Spinning wie Geometrie-Hausaufgaben anfühlt. Deine Hand zeichnet einen Kreis in die eine Richtung, während sich der Staff in die andere dreht, und die Enden ziehen eine Blume. Beim ersten Versuch produzierte ich eher etwas wie einen verwelkten Löwenzahn.","Was half, war, die Form zählbar zu machen. Ein vierblättriges Antispin hat vier Momente, in denen ein Ende direkt aus dem Kreis zeigt. Ich gab jedem einen Beat: oben, Seite, unten, Seite. Dann drehte ich die Musik weit unter mein normales Spin-Tempo und zielte einfach auf die Positionen auf den Beats.","Der Ghost im 3D-Viewer, der zeigt, wo der Staff auf dem nächsten Beat sein sollte, war diese Woche mein bester Freund. Genauso wie der Trail, der meine Blume zeichnete, sodass ich sehen konnte, wann die Petals ungleichmäßig waren. Meist war das untere Petal gestaucht, weil ich das untere Ende des Kreises überhastete.","Nach etwa einer Woche verschob sich etwas. Ich hörte auf, Hand und Staff als zwei Dinge zu denken, und begann, die Blume als eine Form zu fühlen. Das Tempo kam von selbst zurück.","Wenn Antispin dein Gehirn zerstört, soll es das. Gib jedem Petal einen Beat, verlangsame die Musik und lass deinen Körper es herausfinden. Es ist eines der besten Gefühle im Flow, wenn es klappt."]},"siteswaps-for-the-maths-shy":{"title":"Siteswaps für Mathe-Scheue","summary":"Du musst Mathe nicht mögen, um Siteswap zu nutzen; du musst nur wissen, dass größere Zahlen höher gehen.","body":["Siteswap-Notation hat den Ruf, Leute abzuschrecken. Jongleure sagen fröhlich „probier 531“, als würde das etwas erklären. Tut es auch, aber erst, wenn du ein paar Dinge weißt, und diese Dinge sind einfacher, als sie aussehen.","Hier ist fast alles, was du brauchst. Jede Zahl ist ein Throw. Größere Zahlen gehen höher. Ungerade Zahlen kreuzen zur anderen Hand; gerade Zahlen kommen zur selben Hand zurück. Eine 3 ist ein normaler Cascade-Throw. Eine 1 ist ein schneller Zip rüber. Eine 2 ist meist einfach den Ball halten.","Das reicht, um 441 zu lesen: zwei höhere Throws, die auf ihrer eigenen Seite bleiben, dann ein Zip rüber. Du kannst es jetzt versuchen, ohne ein weiteres Wort zu lesen. Throw, Throw, Zip, auf den Beat.","Wenn du noch ein Stück willst: Addiere die Zahlen und teile durch ihre Anzahl, und du bekommst die Ballanzahl. 4 + 4 + 1 = 9, geteilt durch 3 ist 3 Bälle. Wenn die Antwort keine ganze Zahl ist, kann das Pattern nicht jongliert werden. Das ist das ganze berühmte Average Theorem.","In SynthFlow hat jede Jonglier-Bewegung ein Siteswap, und die 3D-Engine animiert direkt daraus. Das heißt, die Figur wirft immer genau die Höhen, die die Zahlen beschreiben, auf den exakten Beats. Ein Siteswap langsam animiert zu sehen, ist der schnellste Weg, den wir kennen, damit die Zahlen Sinn ergeben. Kein Mathe-Abschluss nötig."]},"music-that-fights-you":{"title":"Wenn die Musik gegen dich kämpft","summary":"Ein Track, der gegen die Counts driftet, macht jede Bewegung schwerer; gemessene Tempos und generierte Beats lösen das.","body":["Du hast es wahrscheinlich gespürt: ein Song, den du liebst, eine Bewegung, die du kennst, und irgendwie fühlt sich alles falsch an. Du überhastest, du droppst, du gibst dir die Schuld. Oft liegt das Problem nicht bei dir. Es ist, dass das Tempo des Songs nicht zur Bewegung passt.","Jede Flow-Bewegung hat einen angenehmen Tempo-Bereich. Darunter stocken die Props; darüber werden Würfe flach und hektisch. Ein Track mit 128 BPM unter einer Hoop-Bewegung, die 90 mag, zwingt dich, zwischen Musik und Hoop zu wählen. Die gute Nachricht: Half Time und Double Time helfen – 128 kann eine Bewegung bei 64 tragen, ein Zyklus alle zwei Beats.","Drift ist das subtilere Problem. Wenn die Musik 120 sagt, die Counts aber 116, gleiten beide über eine Minute auseinander, und dein Körper kann nicht beiden folgen. Deshalb nutzt SynthFlow gemessene Tempi für die mitgelieferten Tracks, erzeugt Percussion in jedem exakten Tempo und prüft Tracks von deinem Gerät mit einem Tap-Test.","Wenn ein Track gegen dich arbeitet, kämpfe nicht zurück. Wechsle für die Step zum generierten Beat oder lass dir vom Builder einen Track im richtigen Bereich vorschlagen. Behalte die Songs, die du liebst, fürs freie Spielen, wo nichts zusammenpassen muss.","Musik sollte sich wie ein Partner anfühlen. Wenn sie sich wie ein Gegner anfühlt, wechsle die Musik, nicht deine Bewegung."]},"learning-alongside-my-kid":{"title":"Jonglieren lernen – zusammen mit meinem Kind","summary":"Zwei Anfänger, eine Tasche voller Bälle und eine Regel: Wir feiern Drops genauso laut wie Catches.","body":["Meine Tochter wollte Jonglieren lernen, und mir fiel auf, dass ich es selbst nicht konnte. Also lernten wir zusammen, zehn Minuten nach dem Abendessen, mit je drei Beanbags und einer Regel: Wir jubeln bei Drops genauso laut wie bei Catches.","Die Regel klingt albern. Sie entpuppte sich als der wichtigste Teil. Kinder und Erwachsene verkrampfen, wenn sie einen Fehler für peinlich halten. Verkrampfung macht Würfe schlechter. Bei jedem Drop zu jubeln machte den Boden zum Teil des Spiels und hielt uns beide locker.","Wir begannen mit einem Ball, warfen ihn im Takt von Hand zu Hand, auf Augenhöhe. Es fühlte sich etwa drei Einheiten lang zu leicht an und wurde dann plötzlich wichtig, denn Zwei-Ball-Exchanges funktionieren nur, wenn diese einzelnen Würfe konstant sind. Sie hatte den Exchange vor mir drauf und war unerträglich stolz darauf.","Die gezählte Musik half uns, zusammen zu üben. Gleiches Tempo, gleicher Downbeat, zwei Leute werfen im Takt. Wenn einer von uns das Muster verlor, machte der andere weiter, und der Dropper stieg beim nächsten „eins“ wieder ein.","Nach vier Wochen haben wir beide eine wackelige Cascade. Wichtiger noch: Wir haben eine Gewohnheit, auf die wir uns beide freuen. Wenn du ein Kind hast, das etwas lernen will, lerne es mit ihm. Zusammen Anfänger zu sein wird unterschätzt."]},"why-your-throws-drift-forward":{"title":"Warum deine Würfe nach vorne driften","summary":"Wenn du jede Cascade drei Schritte von deinem Startpunkt entfernt beendest, lehnen sich deine Würfe von dir weg. So holst du sie zurück.","body":["Jeder Jongleur kennt das Laufen. Du startest die Cascade in der Mitte des Raums und beendest sie mit der Nase an der Wand, während du dem Muster Schritt für Schritt hinterherjagst. Es fühlt sich an, als würden die Bälle dich ziehen. Tun sie nicht. Du wirfst sie nach vorne, ein paar Zentimeter auf einmal, und läufst dann hinterher, um aufzuholen.","Die Ursache sind fast immer die Ellbogen. Wenn du angespannt wirst, kippen die Unterarme nach vorne und die Hände lassen den Ball etwas vor dem Körper los. Jeder Wurf landet ein Stück weiter draußen, also findet der nächste Catch weiter draußen statt, also startet der nächste Wurf weiter draußen. Das summiert sich schnell.","Die Korrektur, die ich zuerst unterrichte, ist das Anlegen der Ellbogen. Halte die Ellbogen nah an den Rippen, die Unterarme ungefähr waagerecht, und wirf die Bälle gerade nach oben an deinen Augen vorbei statt nach vorne aus dir heraus. Es fühlt sich einen Tag lang eng an. Dann fühlt es sich ruhig an.","Die zweite Korrektur ist eine Wand. Stell dich mit etwa einem Unterarm Abstand davor und jongliere. Wenn die Würfe driften, sagt dir die Wand das sofort und laut. Zehn Minuten Wandtraining bringen dem Körper schneller bei, wie sich ein aufrechtes Muster anfühlt, als alles, was ich sagen kann.","Der Kameramodus von SynthFlow achtet ebenfalls auf Drift. Er verfolgt, wie viel größer dein Oberkörper für die Kamera über einen Schritt hinweg wirkt, was bedeutet, dass du auf sie zugehst, und stupst dich mit einem kurzen Hinweis an. Der 3D-Coach kann dir auch den Geist eines Vorwärtswurfs neben dem sauberen zeigen, damit du den Unterschied siehst, statt nur davon zu hören.","Drift ist kein Charakterfehler. Es ist eine Spannungsgewohnheit, und Gewohnheiten ändern sich durch Wiederholung. Leg die Ellbogen an, wirf nach oben statt nach außen, und lass die Wand dich ehrlich halten."]},"practising-to-a-click":{"title":"Üben zum Klick","summary":"Ein Metronom klingt nach der langweiligsten Sache der Welt. Es stellte sich als das heraus, was meinen Flow wie Tanzen wirken ließ.","body":["Ich habe mich jahrelang gegen den Klick gewehrt. Musik war für mich der Sinn der Flow Arts, und ein Metronom fühlte sich wie Hausaufgaben an. Dann sah eine Freundin, die Schlagzeug spielt, mir beim Jonglieren zu und sagte freundlich, dass ich jedes Mal schneller wurde, wenn ich mich freute, und langsamer, wenn ich Angst bekam. Sie hatte recht, und ich hatte keine Ahnung.","Also probierte ich eine Woche lang Üben zu nichts als einem Klick. Die erste Entdeckung war, dass ein gleichmäßiger Puls schwerer ist, als er klingt. Mein Two-in-One-Hand-Muster wollte hetzen. Mein Staff-Figure-8 wollte auf der schwachen Seite schleppen. Dem Klick war egal, wie ich mich fühlte; er hielt einfach die Zeit.","Die zweite Entdeckung war, dass der Klick Musik einfacher machte. Nach einer Woche, als ich wieder echte Tracks auflegte, konnte ich fühlen, wo der Beat im Klang saß. Ich hörte auf, gegen Songs mit lockerem Timing anzukämpfen, und begann, mir auszusuchen, an welchem Teil des Grooves ich mich festhake.","Die generierte Percussion von SynthFlow ist eine freundlichere Version des Klicks. Du wählst ein Kit, von einem schlichten Klick bis zu Handtrommeln, und es spielt in jedem Tempo, sodass ein Muster genau in der Geschwindigkeit leben kann, die du halten kannst. Es kann auch leise unter einem Musiktrack als Guide laufen. Ich nutze es immer noch allein für die ersten paar Minuten jeder Session.","Wenn du das ausprobieren willst, wähle ein Muster und ein Tempo, das sich etwas zu langsam anfühlt. Zähle vier Takte laut mit, dann hör auf zu zählen und höre einfach zu. Wenn sich Muster und Klick wie ein Klang anfühlen, erhöhe um vier BPM. Das ist die ganze Methode."]},"staff-in-a-small-apartment":{"title":"Staff in einer kleinen Wohnung","summary":"Ein 1,4 Meter langer Staff und eine 2,4 Meter hohe Decke können zusammenleben. Du musst nur deine Ebenen wählen.","body":["Meine Wohnung hat niedrige Decken, eine Lampe, die ich mag, und einen Nachbarn unten, der nachts arbeitet. Nichts davon ist ideal für Staff-Spinning. Ich habe ein Jahr lang in Parks geübt, bevor ich herausfand, dass der größte Teil meines Trainings doch drinnen stattfinden konnte.","Der Trick sind die Ebenen. Wheel-Plane-Spins, die großen neben dem Körper, brauchen die volle Höhe des Staffs über deinem Kopf. Wall-Plane-Arbeit vor dem Körper braucht Breite, aber weniger Höhe. Floor-Plane-Spins wie der Helicopter brauchen Platz über deinem Kopf, aber nichts um deine Schienbeine. Jeder Raum unterstützt andere Moves.","In meinem Wohnzimmer kann ich Isolations, Front Spins und langsame Figure-8s mit tiefen Armen machen. Im Flur kann ich gar nichts machen, also ist der Flur für Handgelenk-Aufwärmen. Das Schlafzimmer hat die höchste Decke, also findet dort Wheel-Plane-Arbeit statt, langsam, mit abgenommener Lampe, die in einer Schublade verstaut ist.","Kurze Staffs helfen auch. Ein Übungsstaff, der eine Handlänge kürzer ist als mein Performance-Staff, verwandelte viele Beinahe-Unfälle in einfachen Freiraum. Das Timing ändert sich ein wenig, also checke ich meinen Staff in voller Länge einmal pro Woche draußen.","Für die Nachbarn: Übungsmatten und Staffs mit weichen Enden. Ein Drop auf eine Yogamatte ist ein dumpfes Poltern statt ein Knall. Ich halte Indoor-Sessions auch auf gezählte Routinen von zehn Minuten, was den Lärm kurz und das Üben fokussiert hält.","Mit SynthFlow kannst du Bewegungen, die du zu Hause nicht machen kannst, als unerwünscht markieren, damit der Generator sie aus Indoor-Routinen weglässt. Kleine Räume stoppen den Fortschritt nicht. Sie machen dich nur sehr gut in Isolations."]},"hooping-after-40":{"title":"Hooping nach 40","summary":"Ich habe mit 43 zum ersten Mal einen Hoop in die Hand genommen. Mein Rücken, meine Knie und mein Stolz hatten alle eine Meinung. Folgendes hat funktioniert.","body":["Ich habe meinen ersten Erwachsenen-Hoop spontan nach einem Festival gekauft, überzeugt, dass ich furchtbar sein würde. Ich war furchtbar. Und trotzdem habe ich innerhalb eines Monats ganze Songs lang am Bauch gehoopt und nach sechs Monaten einfache Off-Body-Moves gemacht. Das Alter hat mich nicht aufgehalten. Es hat nur verändert, wie ich üben musste.","Die große Lektion war, richtig aufzuwärmen. Hip Circles, Torso Twists und sanfte Knee Bounces dauern drei Minuten und lassen den ersten Hoop der Session geschmeidig statt knarzig wirken. SynthFlow setzt Warm-ups aus gutem Grund an den Anfang jeder Routine, und nach einem steifen Morgen habe ich aufgehört, sie zu überspringen.","Die zweite Lektion war die Hoop-Größe. Ein größerer, etwas schwererer Hoop dreht langsamer, was dir mehr Zeit gibt und weniger vom unteren Rücken verlangt. Ich habe mit einem Hoop angefangen, der im Stehen zwischen Taille und Brust reichte, und ich nutze ihn immer noch für lange Practice-Sessions.","Drittens: pulsiere, kreise nicht. Anfänger schwingen die Hüften oft in einem Kreis, was die Wirbelsäule stärker verdreht als nötig. Ein Pulse nach vorne und hinten, oder seitlich, wenn der Hoop sich bei dir so dreht, hält den Hoop mit weniger Belastung oben. Der 3D-Coach zeigt das deutlich, wenn du auf die Hüften statt auf den Hoop schaust.","Und schließlich: kurz und oft schlägt lang und selten. Zehn Minuten viermal pro Woche haben mir mehr gebracht als eine Stunde am Sonntag. Mein Körper hat sich zwischen den Sessions erholt, und die Moves blieben hängen.","Wenn du über 40 bist und neugierig, fang an. Der Hoop weiß nicht, wie alt du bist."]},"fire-and-the-beginner":{"title":"Feuer und der Anfänger","summary":"Fire Spinning ist der sichtbarste Teil der Flow Arts und der Teil, nach dem Anfänger am häufigsten fragen. Die ehrliche Antwort ist: noch nicht, und nicht allein.","body":["Jede Woche fragt uns jemand, wann SynthFlow Feuer unterrichten wird. Das ist eine berechtigte Frage. Feuer ist schön, und viele Spinner sind in die Szene gekommen, nachdem sie nachts einen Fire Circle gesehen haben. Aber wir werden niemanden dazu coachen, ein Prop anzuzünden, und dieser Beitrag erklärt, warum.","Feuer bringt Gefahren mit sich, die nichts mit Können zu tun haben: Umgang mit Brennstoff, Kleidung, Wind, Zuschauer, Verbrennungen und Löschen. Das lernt man von erfahrenen Leuten persönlich, mit einer ausgebildeten Safety-Person und richtiger Ausrüstung bereit. Eine App kann nicht deinen Fuel Dump, deine Baumwollkleidung oder dein Safety-Towel prüfen.","Was die App tun kann, ist, dir die Skills aufzubauen, die Feuer braucht, bevor du dich ihm überhaupt näherst. Das bedeutet Moves, die du zuverlässig einen ganzen Song lang bei gleichmäßigem Tempo ohne Drops schaffst. Wenn ein Pattern dich zu Hause mit einem Practice-Prop noch überrascht, ist es nicht bereit für Feuer.","Ein nützlicher Test aus der Feuer-Community: Kannst du die Routine mit halb geschlossenen Augen im Dunkeln machen, während jemand mit dir spricht? Feuer ist hell, heiß und laut und nimmt deine Aufmerksamkeit. Dein Körper muss die Moves ohne Aufsicht kennen.","LED-Props sind ein großartiger Zwischenschritt. Sie geben dir den Night-Time-Look, die Trails und die Reaktion des Publikums ohne das Risiko. SynthFlows LED-Style-Pack zeigt, wie deine Patterns beleuchtet aussehen, was auch eine gute Möglichkeit ist, unsaubere Planes zu erkennen.","Wenn du bereit bist, such dir einen lokalen Fire Jam, stell dich vor und bitte darum, zuerst Safety zu lernen. Übe bis dahin mit Practice-Props. Das Feuer wird noch da sein."]},"four-balls-taught-me-patience":{"title":"Vier Bälle haben mir Geduld beigebracht","summary":"Von drei auf vier Bälle zu kommen hat länger gedauert als drei überhaupt zu lernen, und es hat verändert, wie ich über Üben denke.","body":["Drei Bälle haben fünf Wochen gebraucht. Vier haben fünf Monate gebraucht. Niemand hat mich gewarnt, also warne ich dich: Vier Bälle sind nicht drei Bälle plus einer. Es ist ein völlig anderes Pattern, und dein Körper muss es von Grund auf lernen.","In einer Four-Ball Fountain jongliert jede Hand zwei Bälle für sich, und die Bälle kreuzen sich nie. Die Hände wechseln sich meist ab, aber es gibt überhaupt keinen Austausch zwischen ihnen. Alles, was ich darüber gelernt hatte, einen Ball von der anderen Hand zu fangen, war plötzlich nutzlos.","Also ging ich zurück zu einer Hand. Zwei Bälle in der rechten Hand, in Columns, dann Circles, bis ich fünfzig Würfe ohne Nachdenken schaffte. Dann die linke Hand, die dreimal so lange brauchte. Dann beide Hände zusammen, erst synchron, dann alternierend. Die Tempo-Leiter in SynthFlow hat hier geholfen: Ich habe jede Woche unten im Bereich der Fountain angefangen und bin erst nach einem sauberen Run höher gegangen.","Die Geduldslektion kam von den Plateaus. In manchen Wochen verbesserte sich nichts. Ich habe trotzdem Drops und saubere Runs aufgezeichnet, und der Graph zeigte langsamen Fortschritt, auch wenn es sich nach keinem anfühlte. Die Daten machten die langweiligen Wochen erträglich.","Die andere Lektion handelte von Erholung. Vier Bälle ermüdeten meine Unterarme auf eine Weise, wie drei es nie taten. Als ich jeden Tag übte, wurde ich schlechter. Als ich jeden zweiten Tag übte, wurde ich besser. Griffmuskeln brauchen Erholung wie alle anderen.","Wenn du zwischen drei und vier feststeckst, teile das Problem auf, vertrau den langsamen Wochen und gönn deinen Unterarmen einen Tag Pause. Es kommt."]},"the-escalator-and-hand-traffic":{"title":"Der Escalator und die Kunst des Hand-Verkehrs","summary":"Hoop-Hand-Moves sehen wie Magie aus, bis man sieht, dass sie nur sorgfältiges Verkehrsmanagement zwischen zwei Händen sind.","body":["Als ich das erste Mal einen Escalator sah, schien der Hoop die Arme der Hooperin hochzuklettern und wieder herunterzuschweben, endlos, ohne erkennbaren Griff. Ich nahm an, dass es Jahre des Übens braucht. Es brauchte etwa drei Wochen, nachdem ich verstanden hatte, dass es nur ein Muster von Handoffs ist.","Fast jeder Off-Body-Hoop-Move dreht sich darum, welche Hand den Hoop hält, wann sie loslässt und wo die andere Hand ihn trifft. Wenn das Timing zwischen den Händen unscharf ist, wackelt der Hoop aus seiner Plane und der Move fällt auseinander. Wenn das Timing sauber ist, sieht es aus, als würde der Hoop sich von selbst bewegen.","Also fing ich an, Handoffs zu benennen. Über SynthFlows Count sagte ich die Hände laut statt der Zahlen: rechts, links, rechts, links, eine auf jedem Beat. Sie mit der Musik zu sagen, zwang mich zu bemerken, wenn meine linke Hand zu früh griff. Zu frühes Greifen war die Quelle fast jedes Wackelns.","Der zweite Schlüssel war, den Hoop in seiner Plane zu halten. Eine Hand, die sich beim Greifen verdreht, kippt den Hoop, und ein gekippter Hoop ist eine halbe Sekunde später ein gefallener Hoop. Das Plane-Overlay hilft hier, und Üben vor einem Spiegel mit langsamen Tempi ebenso.","Als der Escalator zuverlässig war, kamen andere Hand-Moves schneller. Isolations, Passes und Lassos nutzen dieselbe Idee: klare Handoffs, flache Planes, gleichmäßiges Timing. Die Magie ist nur Verkehrsmanagement."]},"behind-the-back-without-fear":{"title":"Hinter dem Rücken ohne Angst","summary":"Staff-Passes hinter dem Rücken sind die Stelle, an der die meisten Spinner hängen bleiben. Das Problem ist meist nicht das Können, sondern der Drang hinzuschauen.","body":["Monatelang war mein Behind-the-Back-Pass ein Front Pass mit hoffnungsvollem Twist. Ich startete den Move, geriet in Panik, als der Staff aus meinem Blickfeld verschwand, und brachte ihn wieder nach vorne. Der Staff ging nie wirklich hinter meinen Rücken. Mein Gehirn ließ es nicht zu.","Der Durchbruch kam, als ich akzeptierte, dass ich den Move nicht sehen kann. Einen Behind-the-Back-Pass kann man nicht beobachten. Du musst fühlen, wo der Staff ist, von der Hand, die loslässt, und der wartenden Hand vertrauen.","Ich trainierte dieses Gefühl in Zeitlupe. Ohne überhaupt zu spinnen, gab ich den Staff hinter meinem Rücken von Hand zu Hand, mit Blick nach vorne. Dann mit einer langsamen halben Drehung zuerst. Dann unten im Tempo-Bereich des Moves, gezählt. Jeder Schritt fühlte sich albern an. Jeder Schritt funktionierte.","Der 3D-Coach war überraschend nützlich, weil ich die Ansicht drehen und den Move von hinten betrachten konnte. Zu sehen, wo die Hände sich treffen und wie der Staff in der Wall Plane bleibt, während er herumgeht, gab meinem Körper eine Karte, die er von vorne nicht bekommen konnte.","Die zweite Angst war, mich zu treffen. Ein Practice-Staff mit weichen Enden und viel freier Raum haben das gelöst. Als ich wusste, dass ein Fehler nur einen sanften Stups statt eines blauen Flecks kostet, hörte ich auf zu zucken, und das Zucken hatte die Fehler verursacht.","Wenn Behind the Back dir noch Angst macht, verlangsame es stark, nimm den Spin raus und halte den Blick nach vorne. Deine Hände wissen mehr, als du denkst."]},"why-reverse-feels-wrong":{"title":"Warum sich die Reverse Cascade falsch anfühlt","summary":"Die Reverse Cascade nutzt dieselben Hände, dieselben Bälle und denselben Rhythmus wie die Cascade. Warum fühlt es sich also an, als würde man neu anfangen?","body":["Als ich die Reverse Cascade lernte, erwartete ich, dass sie einen Nachmittag dauern würde. Es sind dieselben drei Bälle, dieselben alternierenden Hände und dasselbe Tempo wie bei der Cascade. Sie hat drei Wochen gedauert, und ich konnte nicht herausfinden, warum.","Die Antwort ist die Richtung. In einer normalen Cascade wird jeder Ball von der Innenseite des Musters geworfen und außen gefangen. In einer Reverse Cascade wird der Ball von außen über den ankommenden Ball hinweg geworfen und innen gefangen. Deine Hände machen denselben Rhythmus, aber völlig andere Formen.","Die neue Form bringt dein Timing durcheinander. In der Cascade wirfst du genau in dem Moment, in dem der ankommende Ball zu fallen beginnt. In der Reverse Cascade musst du etwas früher werfen, damit dein Ball über den anderen hinwegkommt. Wirfst du zum alten Zeitpunkt, kollidieren die Bälle.","Ich habe es zuerst mit zwei Bällen hinbekommen. Zwei Bälle, Reverse-Richtung, auf den Beat gezählt, bis es automatisch lief. Dann drei Bälle in langsamem Tempo, während ich die Zählzeiten laut ausgesprochen habe. SynthFlows Ghost-Overlay zeigte mir einen typischen Fehler – einen zu niedrigen Wurf, der den anderen Ball streift – und ich konnte sehen, dass ich genau das tat.","Als es Klick machte, hat es viel freigeschaltet. Cascade und Reverse zu mischen ist die Grundlage vieler Tricks, und die Reverse-Form taucht wieder in Mills Mess auf. Drei Wochen schlecht darin zu sein hat sich gelohnt."]},"making-a-prop-stand-still":{"title":"Isolations: ein Prop scheinbar stillstehen lassen","summary":"Eine Isolation ist eine Bewegung, bei der das Prop scheinbar an einem Ort bleibt, während du dich darum herum bewegst. Es ist die befriedigendste Illusion in den Flow Arts.","body":["Als ich zum ersten Mal eine Staff-Isolation hinbekam, fragte mich mein Freund, wie der Staff schwebt. Er schwebte natürlich nicht. Meine Hände bewegten sich in einem sorgfältigen Kreis, sodass ein Punkt auf dem Staff fest in der Luft blieb. Aber von außen sah es unmöglich aus, und dieses Gefühl ist der Grund, warum ich Isolations liebe.","Jede Isolation funktioniert gleich. Wähle einen Punkt auf dem Prop, meist die Mitte oder ein Ende, und halte diesen Punkt still, während sich der Rest des Props dreht. Deine Hände müssen sich genau entgegengesetzt zu der Richtung bewegen, in die das Prop will. Es ist kontraintuitiv und leicht hypnotisch.","Das Schwierigste ist, dass sich dein Körper mitbewegt. Die Hüften verschieben sich, die Schultern drehen sich, und jede kleine Bewegung zeigt sich als Wackeln im fixierten Punkt. Ich habe vor einem Spiegel geübt, mit einem Stück Klebeband auf dem Glas, das markierte, wo der fixierte Punkt sein sollte. Wenn die Mitte des Props das Klebeband verließ, wusste ich es.","Hoop-Isolations folgen derselben Idee. In SynthFlow schalte ich die Trails im 3D-Viewer ein und beobachte den Coach: Bei einer sauberen Isolation bleibt der Trail um den fixierten Punkt winzig. Als ich das Tempo stark verlangsamte und es nachmachte, konnte ich spüren, wie meine Hände oben in jedem Kreis abdrifteten.","Isolations bauen auch Kontrolle auf, die allem anderen hilft. Sobald du ein Prop stillhalten kannst, kannst du es überall platzieren, wo du willst. Ebenen werden flacher, Übergänge sauberer, und dein Flow wirkt zunehmend beabsichtigt statt zufällig.","Fang langsam an, markiere den fixierten Punkt und beobachte ihn wie ein Falke. Dann zeig es einem Freund und genieße sein Gesicht."]}}`),i={"zero-to-cascade":{name:`Von null zur Cascade in 4 Wochen`,description:`Ein Ball, dann zwei, dann kommt der dritte dazu. Eine kurze Einheit pro Tag reicht: Schließe die Routine jeder Woche ab, um ihre Bewegung zu meistern und die nächste freizuschalten.`,weeks:[{label:`Woche 1 · Ein Ball`},{label:`Woche 2 · Zwei Bälle`},{label:`Woche 3 · Der dritte Ball`},{label:`Woche 4 · Cascade`}]},"staff-foundations":{name:`Staff-Grundlagen`,description:`Wheel Spin und Front Spin, die Figure 8 und der Pass-through: die vier Moves, aus denen fast jeder Staff-Flow entsteht.`,weeks:[{label:`Woche 1 · Wheel Spin`},{label:`Woche 2 · Front Spin`},{label:`Woche 3 · Figure 8`},{label:`Woche 4 · Pass-through`}]},"off-body-hoop":{name:`Off-body Hoop`,description:`Vom Hoop-Spin auf einer Hand über Lassos, Passes, Wedgies und die Isolation, die den Hoop scheinbar schweben lässt.`,weeks:[{label:`Woche 1 · Hand Spin`},{label:`Woche 2 · Lasso und Pass`},{label:`Woche 3 · Wedgie`},{label:`Woche 4 · Isolation`}]}},a={"sf-ambient-70":{name:`Slow Orbit`},"sf-world-75":{name:`Market Steps`},"sf-ambient-80":{name:`Lantern Drift`},"sf-world-85":{name:`Wüstenrad`},"sf-handdrum-90":{name:`Kreistrommel`},"sf-funk-95":{name:`Lose Handgelenke`},"sf-handdrum-100":{name:`Feuerlicht-Hände`},"sf-world-105":{name:`Flussglocken`},"sf-funk-110":{name:`Taschen-Kaskade`},"sf-handdrum-115":{name:`Innenhof-Groove`},"sf-electronic-120":{name:`Neon-Staff`},"sf-funk-125":{name:`Bounce-Pattern`},"sf-electronic-130":{name:`Pixel-Hoop`},"sf-handdrum-135":{name:`Sonnenuntergang-Djembe`},"sf-electronic-140":{name:`LED-Spuren`},"sf-funk-145":{name:`Spin-Zyklus`},"sf-electronic-150":{name:`Strobe-Flow`},"sf-handdrum-155":{name:`Schnelle Handflächen`},"sf-electronic-160":{name:`Nacht-Spinner`}},o={poses:e,routines:t,learn:n,blog:r,progressions:i,music:a};export{r as blog,o as default,n as learn,a as music,e as poses,i as progressions,t as routines};